diff --git a/server/cli/git.ts b/server/cli/git.ts
new file mode 100644
index 0000000..02a3c24
--- /dev/null
+++ b/server/cli/git.ts
@@ -0,0 +1,424 @@
+/**
+ * git — CLI de l'Observatoire Git (LOT 3, parité Codex).
+ *
+ * Wrapper mince sur le SERVICE (`scanGit` / `scanGitDetail` / `listGitRepos`
+ * de `server/services/gitScanner.ts`) — AUCUN appel HTTP, marche sans
+ * serveur, comme `convo`/`chips`. Lecture pure, jamais de contenu de fichier
+ * (git diff/show), texte pur en français.
+ *
+ * Usage (via `bun run git <cmd>`) :
+ *   bun run git status    tableau compact de tous les dépôts, à-risque-d'abord
+ *   bun run git <slug>    détail lisible d'un dépôt + contexte à coller pour Claude
+ *
+ * LOT 8 : les « comptes déclarés » / « notes env » (registre providers
+ * in-repo, `.claude/.workstation-accounts.json`) apparaissent en lignes
+ * CONDITIONNELLES — omises si le dépôt n'a rien déclaré. Mirroir volontaire
+ * de `buildGitContext()` (`src/components/git/gitContext.ts`, LOT 6) : toute
+ * évolution de ces lignes doit être répercutée aux DEUX endroits.
+ */
+import type {
+  GitBranch,
+  GitFileEntry,
+  GitLevel,
+  GitRepoDetail,
+  GitRepoSummary,
+} from '../../src/types/git';
+import { scanGit, scanGitDetail, listGitRepos } from '../services/gitScanner';
+import { isSafeSegment } from '../services/slug';
+import { isHelpRequest, printUsage, fail } from './cliUsage';
+
+/* -------------------------------------------------------------------------- */
+/*  Tri « à risque d'abord » — spec § 02, identityMismatch remonté même clean */
+/* -------------------------------------------------------------------------- */
+
+const LEVEL_ORDER: Record<GitLevel, number> = {
+  blocked: 0,
+  'at-risk': 1,
+  dirty: 2,
+  noteworthy: 3,
+  clean: 4,
+  unknown: 5,
+};
+
+/**
+ * Rang de tri : un dépôt `identityMismatch` mais par ailleurs `clean` ne doit
+ * pas se noyer en bas de liste — remonté au niveau « à noter » (juste après
+ * dirty, avant les vrais dépôts propres). `unknown` reste en dernier : un
+ * échec de scan n'a de toute façon pas d'identité résolue (mismatch=false).
+ */
+function sortRank(r: GitRepoSummary): number {
+  const base = LEVEL_ORDER[r.level];
+  if (r.identityMismatch && base > LEVEL_ORDER.noteworthy) {
+    return LEVEL_ORDER.noteworthy - 0.5;
+  }
+  return base;
+}
+
+function sortAtRiskFirst(repos: GitRepoSummary[]): GitRepoSummary[] {
+  return [...repos].sort((a, b) => sortRank(a) - sortRank(b) || a.name.localeCompare(b.name, 'fr'));
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Formatage partagé (table compacte ET détail)                              */
+/* -------------------------------------------------------------------------- */
+
+const LEVEL_LABEL: Record<GitLevel, string> = {
+  blocked: 'BLOQUÉ',
+  'at-risk': 'À RISQUE',
+  dirty: 'DIRTY',
+  noteworthy: 'À NOTER',
+  clean: 'PROPRE',
+  unknown: 'INCONNU',
+};
+
+function branchCell(r: Pick<GitRepoSummary, 'initial' | 'currentBranch' | 'detachedOid'>): string {
+  if (r.initial) return '(initial)';
+  if (r.currentBranch) return r.currentBranch;
+  if (r.detachedOid) return `(detached ${r.detachedOid.slice(0, 7)})`;
+  return '(detached)';
+}
+
+function dirtyCell(r: GitRepoSummary): string {
+  const { staged, unstaged, untracked, submodules } = r.dirty;
+  const total = staged + unstaged + untracked + submodules;
+  if (total === 0) return '-';
+  const parts: string[] = [];
+  if (staged) parts.push(`${staged} staged`);
+  if (unstaged) parts.push(`${unstaged} modif.`);
+  if (untracked) parts.push(`${untracked} nouv.`);
+  if (submodules) parts.push(`${submodules} sous-mod.`);
+  return `${total} (${parts.join(', ')})`;
+}
+
+/**
+ * Le résumé (`GitRepoSummary`) ne porte que `aheadTotal` (somme d'avance sur
+ * TOUTES les branches locales) — pas de "behindTotal" agrégé, ce compteur
+ * n'existe qu'au niveau branche dans le détail (`GitBranch.track.behind`).
+ * C'est délibéré (§ 07 Q4 de la spec) : le signal exact et critique est
+ * "jamais poussé", pas le retard exact — la colonne reflète donc `aheadTotal`.
+ */
+function syncCell(r: GitRepoSummary): string {
+  return r.aheadTotal > 0 ? `↑${r.aheadTotal} non poussé(s)` : '-';
+}
+
+function identityCell(r: GitRepoSummary): string {
+  if (r.identityMismatch) return `ALERTE (${r.identity.mismatch.length})`;
+  if (r.identity.accountLabel) return r.identity.accountLabel;
+  if (r.identity.scheme === 'none') return '(sans remote)';
+  if (r.identity.scheme === 'multiple') return '(remotes multiples)';
+  if (r.identity.scheme === 'ssh-other') return '(alias inconnu)';
+  return '-';
+}
+
+/**
+ * Compteur "worktrees à nettoyer" — n'appelle `scanGitDetail()` QUE si le
+ * dépôt a effectivement des worktrees (spec LOT 3 : "seulement si pertinent —
+ * sinon reste sur le résumé pour rester rapide"). Un worktree illisible ne
+ * doit jamais se compter "probablement terminé" par défaut (cohérent avec le
+ * scanner) — `scanGitDetail` gère déjà ça, un throw ici retombe sur le total.
+ */
+async function worktreesCell(r: GitRepoSummary): Promise<string> {
+  if (r.worktreeCount === 0) return '-';
+  try {
+    const detail = await scanGitDetail(r.path);
+    const probablyDone = detail.worktrees.filter((w) => !w.isMain && w.probablyDone).length;
+    return probablyDone > 0 ? `${probablyDone}/${r.worktreeCount} à nettoyer` : String(r.worktreeCount);
+  } catch {
+    return String(r.worktreeCount);
+  }
+}
+
+/** Libellés d'affichage des 4 providers connus, dans un ordre stable — mirroir
+ *  de `src/components/git/gitContext.ts:PROVIDER_LABELS`. */
+const PROVIDER_LABELS: readonly ['vercel' | 'cloudflare' | 'convex' | 'workos', string][] = [
+  ['vercel', 'Vercel'],
+  ['cloudflare', 'Cloudflare'],
+  ['convex', 'Convex'],
+  ['workos', 'WorkOS'],
+];
+
+/** « Comptes déclarés : Vercel=... Convex=... » — chaîne vide si rien de déclaré. */
+function providerAccountsLine(detail: GitRepoDetail): string | null {
+  const declared = detail.providerAccounts?.providers;
+  if (!declared) return null;
+  const parts = PROVIDER_LABELS.filter(([key]) => declared[key]).map(([key, label]) => `${label}=${declared[key]}`);
+  return parts.length > 0 ? `Comptes déclarés : ${parts.join(' ')}` : null;
+}
+
+function fileStateCode(f: GitFileEntry): string {
+  if (f.kind === 'untracked') return '??';
+  if (f.kind === 'submodule') return 'SUB';
+  if (f.kind === 'unmerged') return 'UU';
+  return `${f.indexStatus ?? '.'}${f.worktreeStatus ?? '.'}`;
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Table texte alignée (pas de dépendance externe)                           */
+/* -------------------------------------------------------------------------- */
+
+function renderTable(headers: string[], rows: string[][]): string {
+  const widths = headers.map((h, i) => Math.max(h.length, ...rows.map((r) => (r[i] ?? '').length)));
+  const line = (cols: string[]) => cols.map((c, i) => (c ?? '').padEnd(widths[i])).join('  ');
+  const separator = widths.map((w) => '-'.repeat(w)).join('  ');
+  return [line(headers), separator, ...rows.map(line)].join('\n');
+}
+
+/* -------------------------------------------------------------------------- */
+/*  bun run git status                                                        */
+/* -------------------------------------------------------------------------- */
+
+async function cmdStatus(): Promise<void> {
+  const repos = await scanGit();
+  const sorted = sortAtRiskFirst(repos);
+
+  const rows: string[][] = [];
+  for (const r of sorted) {
+    // eslint-disable-next-line no-await-in-loop -- séquentiel par design : seuls
+    // les dépôts AVEC worktrees déclenchent un scanGitDetail supplémentaire ;
+    // cardinalité faible (~dizaines de dépôts, worktrees non-main rares).
+    const worktrees = await worktreesCell(r);
+    rows.push([
+      LEVEL_LABEL[r.level],
+      r.name,
+      branchCell(r),
+      dirtyCell(r),
+      syncCell(r),
+      identityCell(r),
+      worktrees,
+    ]);
+  }
+
+  const table = renderTable(
+    ['Niveau', 'Projet', 'Branche', 'Fichiers modifiés', 'Synchro', 'Identité', 'Worktrees'],
+    rows,
+  );
+
+  const lines = ['VERDICT: READ', `${repos.length} dépôt(s) scanné(s) sous projectsRoot().`, '', table];
+
+  const failed = sorted.filter((r) => r.level === 'unknown');
+  if (failed.length > 0) {
+    lines.push('', 'Échecs de scan (jamais affichés "propre") :');
+    for (const r of failed) {
+      lines.push(`  - ${r.name} : ${r.scanError ?? '(raison inconnue)'}`);
+    }
+  }
+
+  process.stdout.write(lines.join('\n') + '\n');
+}
+
+/* -------------------------------------------------------------------------- */
+/*  bun run git <slug> — détail + contexte à coller pour Claude (spec § 01)   */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * Gabarit EXACT de la spec § 01 : lignes conditionnelles (pas de bruit quand
+ * vide) pour Dirty et ALERTE identité, mais la ligne finale (branches locales
+ * / worktrees / stash) reste toujours présente avec "aucun" plutôt qu'omise —
+ * c'est le comportement montré par l'exemple de la spec.
+ */
+function buildContextSnippet(detail: GitRepoDetail): string {
+  const lines: string[] = [];
+  lines.push(`Contexte git — ${detail.name} (${detail.path})`);
+
+  let branchLine: string;
+  if (detail.initial) {
+    branchLine = 'Branche : (initial) — aucun commit';
+  } else if (!detail.currentBranch) {
+    const oid = detail.detachedOid ? detail.detachedOid.slice(0, 7) : '?';
+    branchLine = `Branche : HEAD détaché (${oid})`;
+  } else {
+    const b = detail.branches.find((x) => x.name === detail.currentBranch);
+    let sync: string;
+    if (!b || !b.upstream) {
+      sync = 'aucune amont configurée (jamais poussée nulle part)';
+    } else if (b.track.gone) {
+      sync = `amont "${b.upstream}" supprimée [gone]`;
+    } else if (b.track.ahead > 0) {
+      sync = `${b.track.ahead} commit(s) en avance sur ${b.upstream} (jamais poussés)`;
+    } else if (b.track.behind > 0) {
+      sync = `à jour, ${b.track.behind} commit(s) en retard sur ${b.upstream}`;
+    } else {
+      sync = `à jour avec ${b.upstream}`;
+    }
+    branchLine = `Branche : ${detail.currentBranch} · ${sync}`;
+  }
+  lines.push(branchLine);
+
+  const dirtyTotal =
+    detail.dirty.staged + detail.dirty.unstaged + detail.dirty.untracked + detail.dirty.submodules;
+  if (dirtyTotal > 0) {
+    const names = detail.files.map((f) => `${f.path} (${fileStateCode(f)})`).join(', ');
+    lines.push(`Dirty : ${dirtyTotal} fichier(s) modifié(s) — ${names}`);
+  }
+
+  if (detail.identityMismatch) {
+    const detailText = detail.identity.mismatch.map((m) => m.detail).join(' ; ');
+    lines.push(`ALERTE identité : ${detailText}`);
+  }
+
+  const providerLine = providerAccountsLine(detail);
+  if (providerLine) lines.push(providerLine);
+  if (detail.providerAccounts?.envNotes) {
+    lines.push(`Notes env : ${detail.providerAccounts.envNotes}`);
+  }
+
+  const branchNames = detail.branches.map((b) => b.name).join(', ') || 'aucune';
+  const extraWorktrees = detail.worktrees.filter((w) => !w.isMain);
+  const worktreeSummary =
+    extraWorktrees.length === 0
+      ? 'aucun'
+      : `${extraWorktrees.length} (${extraWorktrees.map((w) => w.branch ?? '(détaché)').join(', ')})`;
+  const stashSummary =
+    detail.stashes.length === 0
+      ? 'aucun'
+      : `${detail.stashes.length} (${detail.stashes.map((s) => s.ref).join(', ')})`;
+  lines.push(`Branches locales : ${branchNames} · Worktrees : ${worktreeSummary} · Stash : ${stashSummary}`);
+
+  return lines.join('\n');
+}
+
+function branchDetailLine(b: GitBranch): string {
+  const track = b.track.gone
+    ? '[upstream supprimé]'
+    : b.upstream
+      ? `upstream ${b.upstream}` +
+        (b.track.ahead ? `, ↑${b.track.ahead}` : '') +
+        (b.track.behind ? `, ↓${b.track.behind}` : '')
+      : '(sans upstream)';
+  const merged = b.mergedIntoDefault ? ' — fusionnée dans la branche par défaut, sûre à supprimer' : '';
+  return `  - ${b.name} · ${track}${merged}`;
+}
+
+function renderDetail(detail: GitRepoDetail): string {
+  const lines: string[] = [];
+  lines.push('VERDICT: READ');
+  lines.push(`${detail.name} (${detail.path})`);
+  lines.push(`Niveau : ${LEVEL_LABEL[detail.level]} · Branche : ${branchCell(detail)}`);
+
+  if (detail.opInProgress) {
+    lines.push(`Opération en cours : ${detail.opInProgress} — dépôt bloqué tant que non résolu/avorté.`);
+  }
+
+  const dirtyTotal =
+    detail.dirty.staged + detail.dirty.unstaged + detail.dirty.untracked + detail.dirty.submodules;
+  if (dirtyTotal > 0) {
+    lines.push(`Dirty : ${dirtyTotal} fichier(s) modifié(s) :`);
+    for (const f of detail.files) lines.push(`  - ${f.path} (${fileStateCode(f)})`);
+  }
+
+  if (detail.aheadTotal > 0) {
+    lines.push(
+      `Synchro : ${detail.aheadTotal} commit(s) en avance (toutes branches confondues, jamais poussés).`,
+    );
+  }
+
+  const id = detail.identity;
+  lines.push(`Identité : ${id.accountLabel ?? id.scheme} · Email : ${id.effectiveEmail ?? '(non défini)'}`);
+  if (detail.identityMismatch) {
+    for (const m of id.mismatch) lines.push(`ALERTE identité (${m.kind}) : ${m.detail}`);
+  }
+
+  // LOT 8 — comptes providers déclarés in-repo (lecture seule, jamais écrits
+  // par ce service). "non déclaré" plutôt qu'une ligne muette : le geste
+  // "déclarer les comptes" (UI) doit être visible comme une action possible.
+  const providerLine = providerAccountsLine(detail);
+  if (providerLine) {
+    lines.push(providerLine);
+  } else {
+    lines.push('Comptes déclarés : non déclaré (.claude/.workstation-accounts.json absent)');
+  }
+  if (detail.providerAccounts?.envNotes) {
+    lines.push(`Notes env : ${detail.providerAccounts.envNotes}`);
+  }
+  if (detail.providerAccountsWarning) {
+    lines.push(`Avertissement registre providers : ${detail.providerAccountsWarning}`);
+  }
+
+  lines.push('', `Branches locales (${detail.branches.length}) :`);
+  if (detail.branches.length === 0) {
+    lines.push('  (aucune)');
+  } else {
+    for (const b of detail.branches) lines.push(branchDetailLine(b));
+  }
+
+  if (detail.stashes.length > 0) {
+    lines.push('', `Stashes (${detail.stashes.length}) :`);
+    for (const s of detail.stashes) {
+      lines.push(`  - ${s.ref} · ${s.message}${s.date ? ` · ${s.date}` : ''}`);
+    }
+  }
+
+  const extraWorktrees = detail.worktrees.filter((w) => !w.isMain);
+  if (extraWorktrees.length > 0) {
+    lines.push('', `Worktrees (${extraWorktrees.length}) :`);
+    for (const w of extraWorktrees) {
+      const branch = w.branch ?? (w.detachedOid ? `(detached ${w.detachedOid.slice(0, 7)})` : '(détaché)');
+      const flags = [
+        w.locked ? 'verrouillé' : null,
+        w.prunable ? 'prunable' : null,
+        w.probablyDone ? 'probablement terminé — sûr à nettoyer' : null,
+      ]
+        .filter(Boolean)
+        .join(', ');
+      lines.push(`  - ${w.path} · ${branch}${flags ? ` · ${flags}` : ''}`);
+    }
+  }
+
+  lines.push('', '--- Contexte git — à coller pour Claude ---', buildContextSnippet(detail), '---');
+
+  if (detail.scanError) {
+    lines.push('', `Erreur de scan : ${detail.scanError}`);
+  }
+
+  return lines.join('\n');
+}
+
+async function cmdDetail(slug: string): Promise<void> {
+  const refs = await listGitRepos();
+  const ref = refs.find((r) => r.slug === slug);
+  if (!ref) {
+    fail(`dépôt "${slug}" introuvable — "bun run git status" liste les dépôts connus.`);
+  }
+  const detail = await scanGitDetail(ref.path);
+  process.stdout.write(renderDetail(detail) + '\n');
+}
+
+/* -------------------------------------------------------------------------- */
+/*  main                                                                      */
+/* -------------------------------------------------------------------------- */
+
+const SUBCOMMANDS = 'status | <slug>';
+
+async function main() {
+  const [cmd, ...rest] = process.argv.slice(2);
+
+  if (isHelpRequest(cmd)) {
+    printUsage('git', SUBCOMMANDS);
+    process.stdout.write(
+      '\n' +
+        "bun run git status   tableau compact de tous les dépôts, triés à-risque-d'abord\n" +
+        'bun run git <slug>   détail lisible d\'un dépôt (fichiers, branches, worktrees, stash)\n' +
+        '                     + contexte à coller pour Claude\n',
+    );
+    return;
+  }
+
+  if (cmd === 'status') {
+    if (rest[0] === '--help' || rest[0] === '-h') {
+      process.stdout.write('Usage: bun run git status\n');
+      return;
+    }
+    await cmdStatus();
+    return;
+  }
+
+  // isHelpRequest(cmd) déjà retourné plus haut si cmd était undefined — cette
+  // coercition ne change donc rien au runtime, elle satisfait juste le typage.
+  const slugArg = cmd ?? '';
+  if (!isSafeSegment(slugArg)) {
+    fail(`slug invalide : "${slugArg}"`);
+  }
+  await cmdDetail(slugArg);
+}
+
+main().catch((err) => fail((err as Error).message));

diff --git a/server/services/gitScanner.ts b/server/services/gitScanner.ts
new file mode 100644
index 0000000..810c677
--- /dev/null
+++ b/server/services/gitScanner.ts
@@ -0,0 +1,1546 @@
+/**
+ * Observatoire Git — scanner cœur (LOT 1).
+ *
+ * Produit, pour chaque dépôt sous `projectsRoot()` (workstation INCLUSE), un
+ * `GitRepoSummary` fiable avec niveau d'alerte — lecture pure, jamais de
+ * mutation git. Suit le pattern `execFile` argv de `server/lib/git.ts`
+ * (JAMAIS de shell) et le pattern cache/énumération de
+ * `server/services/projectScanner.ts`, corrigé sur ses deux angles morts pour
+ * ce sous-système : (1) `SELF_FOLDER` n'est PAS exclu ici — la workstation
+ * doit figurer dans son propre observatoire ; (2) la concurrence du scan
+ * multi-dépôts est BORNÉE (sémaphore), là où `Promise.allSettled` du
+ * projectScanner ne l'est pas.
+ *
+ * Un dépôt en échec de scan (execFile, timeout, parsing) reçoit TOUJOURS
+ * `level: 'unknown'` + `scanError` renseigné — jamais 'clean' par défaut : la
+ * fausse tranquillité est le pire résultat possible de ce produit (§ 00 du
+ * plan de chantier).
+ */
+import { execFile } from 'node:child_process';
+import fs from 'node:fs/promises';
+import path from 'node:path';
+import { promisify } from 'node:util';
+
+import {
+  GitRepoDetailSchema,
+  GitRepoSummarySchema,
+  type GitBranch,
+  type GitFileEntry,
+  type GitIdentity,
+  type GitIdentityMismatch,
+  type GitLevel,
+  type GitOpInProgress,
+  type GitRefsFreshness,
+  type GitRepoDetail,
+  type GitRepoSummary,
+  type GitStashEntry,
+  type GitWorktreeEntry,
+} from '../../src/types/git';
+import {
+  parseProviderAccountsFile,
+  PROVIDER_ACCOUNTS_RELATIVE_PATH,
+  type ProviderAccountsFile,
+} from '../../src/types/providerAccounts';
+import { GITHUB_ACCOUNTS, projectsRoot, SCAN_CACHE_TTL_MS } from '../config';
+import { slugify } from './slug';
+
+const execFileAsync = promisify(execFile);
+
+/** Timeout par commande git (spec § 03) — un dépôt lent ne doit jamais geler le scan. */
+const GIT_TIMEOUT_MS = 5_000;
+/** Sortie max par commande (10 MiB) — large pour un porcelain --branch -z sur un gros dépôt. */
+const GIT_MAX_BUFFER = 10 * 1024 * 1024;
+/** Bornes du sémaphore de concurrence (spec : 4 à 6 dépôts en vol). */
+const MAX_CONCURRENT_SCANS = 5;
+
+/* -------------------------------------------------------------------------- */
+/*  Sémaphore borné — concurrence des scans par dépôt                         */
+/* -------------------------------------------------------------------------- */
+
+class Semaphore {
+  private active = 0;
+  private readonly queue: Array<() => void> = [];
+
+  constructor(private readonly max: number) {}
+
+  private acquire(): Promise<void> {
+    if (this.active < this.max) {
+      this.active++;
+      return Promise.resolve();
+    }
+    return new Promise((resolve) => {
+      this.queue.push(() => {
+        this.active++;
+        resolve();
+      });
+    });
+  }
+
+  private release(): void {
+    this.active--;
+    const next = this.queue.shift();
+    if (next) next();
+  }
+
+  async run<T>(fn: () => Promise<T>): Promise<T> {
+    await this.acquire();
+    try {
+      return await fn();
+    } finally {
+      this.release();
+    }
+  }
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Énumération des dépôts sous projectsRoot()                                */
+/* -------------------------------------------------------------------------- */
+
+export interface GitRepoRef {
+  slug: string;
+  name: string;
+  path: string;
+}
+
+async function hasDotGit(repoDir: string): Promise<boolean> {
+  try {
+    // lstat (pas stat) : un .git peut être un symlink pointant vers un gitdir
+    // externe (rare mais valide) — son existence suffit, on ne le déréférence
+    // pas ici (resolveGitDir() gère la résolution réelle plus loin).
+    await fs.lstat(path.join(repoDir, '.git'));
+    return true;
+  } catch {
+    return false;
+  }
+}
+
+/**
+ * Énumère {slug, name, path} de chaque dossier direct sous projectsRoot() qui
+ * porte un `.git` (dossier OU fichier gitdir de worktree lié). Exclut les noms
+ * commençant par '.' ; N'EXCLUT PAS SELF_FOLDER ('workstation'). Utilisée par
+ * `scanGit()` ET, au LOT 3, par la route pour résoudre/valider un `:slug` sans
+ * refaire un scan git complet.
+ */
+export async function listGitRepos(): Promise<GitRepoRef[]> {
+  const root = projectsRoot();
+  let dirents: import('node:fs').Dirent[];
+  try {
+    dirents = await fs.readdir(root, { withFileTypes: true });
+  } catch {
+    return [];
+  }
+
+  const candidates: string[] = [];
+  for (const d of dirents) {
+    if (d.name.startsWith('.')) continue;
+    if (d.isDirectory()) {
+      candidates.push(d.name);
+      continue;
+    }
+    if (d.isSymbolicLink()) {
+      try {
+        // fs.stat (JAMAIS Dirent.isDirectory()/fs.lstat) DÉRÉFÉRENCE le lien :
+        // c'est le seul moyen de savoir si la CIBLE d'un symlink est un
+        // dossier. Le Dirent renvoyé par readdir décrit le lien lui-même, pas
+        // sa cible — un dossier projet symlinké sous projectsRoot() resterait
+        // sinon invisible de l'observatoire (fausse tranquillité proscrite).
+        // eslint-disable-next-line no-await-in-loop -- cardinalité ~dizaines, même borne que hasDotGit ci-dessous.
+        const target = await fs.stat(path.join(root, d.name));
+        if (target.isDirectory()) candidates.push(d.name);
+      } catch {
+        // Lien cassé ou cible inaccessible : ignoré silencieusement, jamais de crash.
+      }
+    }
+  }
+
+  const results: GitRepoRef[] = [];
+  for (const name of candidates) {
+    const repoPath = path.join(root, name);
+    // eslint-disable-next-line no-await-in-loop -- readdir cardinality is small (~dozens); sequential lstat keeps this simple and cheap.
+    if (await hasDotGit(repoPath)) {
+      results.push({ slug: slugify(name), name, path: repoPath });
+    }
+  }
+  return results;
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Invocation git bas niveau                                                 */
+/* -------------------------------------------------------------------------- */
+
+/** `execFile` en argv (JAMAIS de shell), timeout 5 s — pattern `server/lib/git.ts`. */
+async function runGit(repoDir: string, args: string[]): Promise<string> {
+  const { stdout } = await execFileAsync('git', ['-C', repoDir, ...args], {
+    timeout: GIT_TIMEOUT_MS,
+    maxBuffer: GIT_MAX_BUFFER,
+  });
+  return stdout;
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Parsing : git status --porcelain=v2 --branch -z                          */
+/* -------------------------------------------------------------------------- */
+
+interface ParsedStatus {
+  currentBranch: string | null;
+  detachedOid: string | null;
+  initial: boolean;
+  dirty: { staged: number; unstaged: number; untracked: number; submodules: number };
+}
+
+/**
+ * Parse la sortie NUL-terminée de `status --porcelain=v2 --branch -z`.
+ *
+ * Ordre des en-têtes garanti par git : `# branch.oid` PUIS `# branch.head`
+ * (jamais l'inverse) — on peut donc mémoriser l'oid provisoirement avant de
+ * savoir si HEAD est détaché, et le rejeter si une branche nommée suit.
+ *
+ * Une entrée de renommage (marqueur '2') consomme DEUX tokens NUL-terminés
+ * consécutifs (le descripteur, puis l'ancien chemin) — vérifié empiriquement
+ * (git 2.50) : `2 R. N... <mode>x3 <hash>x2 R100 nouveauNom\0ancienNom\0`.
+ */
+function parseStatusPorcelainV2(raw: string): ParsedStatus {
+  // Le dernier '\0' de la sortie produit un token vide terminal : on le laisse
+  // dans le tableau, la boucle ci-dessous l'ignore (longueur nulle, aucun
+  // marqueur reconnu) sans risque de désaligner l'index des renames.
+  const tokens = raw.split('\0');
+
+  let currentBranch: string | null = null;
+  let provisionalOid: string | null = null;
+  let detached = false;
+  let initial = false;
+  let staged = 0;
+  let unstaged = 0;
+  let untracked = 0;
+  let submodules = 0;
+
+  for (let i = 0; i < tokens.length; i++) {
+    const line = tokens[i];
+    if (line.length === 0) continue;
+
+    if (line.startsWith('# branch.oid ')) {
+      const oid = line.slice('# branch.oid '.length);
+      if (oid === '(initial)') {
+        initial = true;
+      } else {
+        provisionalOid = oid;
+      }
+      continue;
+    }
+    if (line.startsWith('# branch.head ')) {
+      const head = line.slice('# branch.head '.length);
+      if (head === '(detached)') {
+        detached = true;
+        currentBranch = null;
+      } else {
+        currentBranch = head;
+      }
+      continue;
+    }
+    if (line.startsWith('# branch.upstream ') || line.startsWith('# branch.ab ')) {
+      // Non authoritatif ici : `for-each-ref` couvre TOUTES les branches
+      // locales (dont celle-ci), c'est la source retenue pour ahead/behind.
+      continue;
+    }
+    if (line.startsWith('#')) continue; // en-tête inconnu/futur, ignoré sans casser le parsing.
+
+    const marker = line[0];
+    if (marker === '?') {
+      untracked++;
+      continue;
+    }
+    if (marker === '!') {
+      continue; // ignored, jamais demandé (pas de --ignored)
+    }
+    if (marker === 'u') {
+      // Conflit non résolu : compté côté "unstaged" (nécessite une action avant
+      // tout commit) — le schéma LOT 1 n'a pas de compartiment dédié.
+      unstaged++;
+      continue;
+    }
+    if (marker === '1' || marker === '2') {
+      const fields = line.split(' ');
+      const xy = fields[1] ?? '';
+      const sub = fields[2] ?? '';
+      if (sub.startsWith('S')) {
+        submodules++;
+      } else {
+        if (xy[0] && xy[0] !== '.') staged++;
+        if (xy[1] && xy[1] !== '.') unstaged++;
+      }
+      if (marker === '2') {
+        // Consomme le token suivant (ancien chemin, pas de marqueur propre).
+        i++;
+      }
+      continue;
+    }
+    // Marqueur inconnu (git plus récent) : ignoré plutôt que de faire échouer
+    // tout le scan du dépôt pour une ligne qu'on ne sait pas encore lire.
+  }
+
+  const detachedOid = detached ? provisionalOid : null;
+
+  return {
+    currentBranch,
+    detachedOid,
+    initial,
+    dirty: { staged, unstaged, untracked, submodules },
+  };
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Parsing : git for-each-ref refs/heads (TOUTES les branches locales)       */
+/* -------------------------------------------------------------------------- */
+
+interface BranchTrackInfo {
+  name: string;
+  upstream: string | null;
+  ahead: number;
+  behind: number;
+  gone: boolean;
+  lastCommitDate: string | null;
+}
+
+const FOR_EACH_REF_FORMAT =
+  '%(refname:short)%09%(upstream:short)%09%(upstream:track)%09%(committerdate:iso8601-strict)';
+
+/**
+ * C'est CETTE commande (pas `status`) qui attrape les commits jamais poussés
+ * d'une branche NON checkoutée (le cas brillance-d-cor-inc/master, +56) :
+ * `status --branch` ne calcule l'avance/retard QUE pour la branche courante.
+ *
+ * Vérifié empiriquement (git 2.50) : `%(upstream:short)` reste résolu même
+ * quand la ref amont a été prunée (`[gone]`) — donc `upstream === null`
+ * signifie précisément "aucune amont configurée", jamais "amont disparue".
+ */
+function parseForEachRef(raw: string): BranchTrackInfo[] {
+  return raw
+    .split('\n')
+    .filter((line) => line.trim().length > 0)
+    .map((line) => {
+      const [name, upstreamRaw, trackRaw, dateRaw] = line.split('\t');
+      const upstream = upstreamRaw && upstreamRaw.length > 0 ? upstreamRaw : null;
+      const track = trackRaw ?? '';
+      const gone = track === '[gone]';
+      const aheadMatch = track.match(/ahead (\d+)/);
+      const behindMatch = track.match(/behind (\d+)/);
+      return {
+        name,
+        upstream,
+        ahead: aheadMatch ? Number(aheadMatch[1]) : 0,
+        behind: behindMatch ? Number(behindMatch[1]) : 0,
+        gone,
+        lastCommitDate: dateRaw && dateRaw.length > 0 ? dateRaw : null,
+      };
+    });
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Parsing : git stash list                                                  */
+/* -------------------------------------------------------------------------- */
+
+interface StashInfo {
+  ref: string;
+  message: string;
+  date: string | null;
+}
+
+function parseStashList(raw: string): StashInfo[] {
+  return raw
+    .split('\n')
+    .filter((line) => line.trim().length > 0)
+    .map((line) => {
+      const [ref, message, date] = line.split('\t');
+      return { ref, message: message ?? '', date: date && date.length > 0 ? date : null };
+    });
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Parsing : git worktree list --porcelain                                   */
+/* -------------------------------------------------------------------------- */
+
+interface WorktreeInfo {
+  path: string;
+  branch: string | null;
+  detachedOid: string | null;
+  isMain: boolean;
+  locked: boolean;
+  prunable: boolean;
+}
+
+/**
+ * Blocs séparés par une ligne vide, un worktree par bloc. Le worktree
+ * PRINCIPAL est toujours listé en premier (comportement documenté de git) —
+ * `isMain` s'appuie dessus, jamais deviné autrement.
+ */
+function parseWorktreeList(raw: string): WorktreeInfo[] {
+  const blocks: string[][] = [];
+  let current: string[] = [];
+  for (const line of raw.split('\n')) {
+    if (line.trim() === '') {
+      if (current.length > 0) {
+        blocks.push(current);
+        current = [];
+      }
+      continue;
+    }
+    current.push(line);
+  }
+  if (current.length > 0) blocks.push(current);
+
+  return blocks.map((block, idx) => {
+    let wtPath = '';
+    let headOid: string | null = null;
+    let branch: string | null = null;

+    let branch: string | null = null;
+    let detached = false;
+    let locked = false;
+    let prunable = false;
+    for (const line of block) {
+      if (line.startsWith('worktree ')) wtPath = line.slice('worktree '.length);
+      else if (line.startsWith('HEAD ')) headOid = line.slice('HEAD '.length);
+      else if (line.startsWith('branch ')) {
+        branch = line.slice('branch '.length).replace(/^refs\/heads\//, '');
+      } else if (line === 'detached') detached = true;
+      else if (line.startsWith('locked')) locked = true;
+      else if (line.startsWith('prunable')) prunable = true;
+    }
+    return {
+      path: wtPath,
+      branch,
+      detachedOid: detached ? headOid : null,
+      isMain: idx === 0,
+      locked,
+      prunable,
+    };
+  });
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Opération en cours (.git/MERGE_HEAD, rebase-merge/, ...)                  */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * Résout le VRAI gitdir : `.git` est un dossier pour un dépôt principal, mais
+ * un FICHIER (`gitdir: <chemin>`) pour un worktree lié. Vérifié empiriquement
+ * (git 2.50) : le chemin écrit est déjà absolu pour un worktree lié classique.
+ */
+export async function resolveGitDir(repoDir: string): Promise<string | null> {
+  const dotGitPath = path.join(repoDir, '.git');
+  let st;
+  try {
+    st = await fs.lstat(dotGitPath);
+  } catch {
+    return null;
+  }
+  if (st.isDirectory()) return dotGitPath;
+  if (st.isFile()) {
+    try {
+      const content = await fs.readFile(dotGitPath, 'utf8');
+      const m = content.match(/^gitdir:\s*(.+?)\s*$/m);
+      if (!m) return null;
+      const raw = m[1];
+      return path.isAbsolute(raw) ? raw : path.resolve(repoDir, raw);
+    } catch {
+      return null;
+    }
+  }
+  return null;
+}
+
+const OP_MARKERS: ReadonlyArray<readonly [string, GitOpInProgress]> = [
+  ['MERGE_HEAD', 'merge'],
+  ['rebase-merge', 'rebase'],
+  ['rebase-apply', 'rebase'],
+  ['CHERRY_PICK_HEAD', 'cherry-pick'],
+  ['BISECT_LOG', 'bisect'],
+];
+
+async function detectOpInProgress(repoDir: string): Promise<GitOpInProgress | null> {
+  const gitDir = await resolveGitDir(repoDir);
+  if (!gitDir) return null;
+  for (const [marker, kind] of OP_MARKERS) {
+    try {
+      // eslint-disable-next-line no-await-in-loop -- au plus 5 stats fixes, l'ordre de priorité (merge > rebase > cherry-pick > bisect) importe.
+      await fs.stat(path.join(gitDir, marker));
+      return kind;
+    } catch {
+      // marqueur absent, on continue
+    }
+  }
+  return null;
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Fraîcheur des refs distantes (LOT 4) — mtime FETCH_HEAD, repli refs/      */
+/*  remotes/ — jamais "à jour" affiché sans preuve (spec § 02)                */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * Mtime le plus RÉCENT parmi tous les fichiers sous `dir` (récursif) ; `null`
+ * si le dossier est absent ou ne contient aucun fichier. Sert de repli quand
+ * `FETCH_HEAD` n'existe pas : un `git push -u` écrit quand même la ref de
+ * suivi distant locale (`refs/remotes/<remote>/<branche>`) SANS créer
+ * `FETCH_HEAD` (vérifié empiriquement, git 2.50) — un dépôt jamais fetché mais
+ * poussé avec `-u` a donc une fraîcheur dérivable malgré tout.
+ */
+async function newestMtimeUnder(dir: string): Promise<Date | null> {
+  let entries: import('node:fs').Dirent[];
+  try {
+    entries = await fs.readdir(dir, { withFileTypes: true });
+  } catch {
+    return null;
+  }
+  let newest: Date | null = null;
+  for (const entry of entries) {
+    const full = path.join(dir, entry.name);
+    if (entry.isDirectory()) {
+      // eslint-disable-next-line no-await-in-loop -- arbre refs/remotes minuscule (quelques fichiers/dossiers par remote), simplicité > micro-parallélisme.
+      const sub = await newestMtimeUnder(full);
+      if (sub && (!newest || sub > newest)) newest = sub;
+      continue;
+    }
+    if (!entry.isFile()) continue;
+    try {
+      // eslint-disable-next-line no-await-in-loop -- voir ci-dessus.
+      const st = await fs.stat(full);
+      if (!newest || st.mtime > newest) newest = st.mtime;
+    } catch {
+      // fichier disparu entre le readdir et le stat (rare, non bloquant) : ignoré.
+    }
+  }
+  return newest;
+}
+
+const MS_PER_DAY = 24 * 60 * 60 * 1000;
+
+/**
+ * Fraîcheur des refs distantes d'UN dépôt (spec § 01/§ 02, LOT 4) — alimente
+ * la colonne "synchro" (« à jour (refs vieilles de N j) ») sans jamais fetcher
+ * le réseau (Q4 tranchée : refs locales uniquement). `null`/`null` si rien
+ * n'existe (dépôt sans remote jamais fetché ni poussé avec suivi) : c'est le
+ * seul état honnête, jamais "à jour" sans preuve.
+ */
+async function computeRefsFreshness(repoDir: string): Promise<GitRefsFreshness> {
+  const gitDir = await resolveGitDir(repoDir);
+  if (!gitDir) return { lastFetch: null, ageDays: null };
+
+  let mtime: Date | null = null;
+  try {
+    const st = await fs.stat(path.join(gitDir, 'FETCH_HEAD'));
+    mtime = st.mtime;
+  } catch {
+    mtime = await newestMtimeUnder(path.join(gitDir, 'refs', 'remotes'));
+  }
+  if (!mtime) return { lastFetch: null, ageDays: null };
+
+  const ageDays = Math.max(0, Math.floor((Date.now() - mtime.getTime()) / MS_PER_DAY));
+  return { lastFetch: mtime.toISOString(), ageDays };
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Identité git (LOT 2) — alias/compte détecté, email effectif, mismatch     */
+/* -------------------------------------------------------------------------- */
+
+type GithubAccountKey = keyof typeof GITHUB_ACCOUNTS;
+type GithubAccountInfo = (typeof GITHUB_ACCOUNTS)[GithubAccountKey];
+
+/** Table indexable par alias — évite un cast répété à chaque lookup. */
+const GITHUB_ACCOUNTS_BY_ALIAS: Record<string, GithubAccountInfo> = GITHUB_ACCOUNTS;
+
+function findAccountByOwner(owner: string): (GithubAccountInfo & { key: string }) | null {
+  for (const [key, info] of Object.entries(GITHUB_ACCOUNTS_BY_ALIAS)) {
+    // GitHub est insensible à la casse sur les owners.
+    if (info.owner.toLowerCase() === owner.toLowerCase()) return { key, ...info };
+  }
+  return null;
+}
+
+function findAccountByName(account: string): (GithubAccountInfo & { key: string }) | null {
+  for (const [key, info] of Object.entries(GITHUB_ACCOUNTS_BY_ALIAS)) {
+    if (info.account === account) return { key, ...info };
+  }
+  return null;
+}
+
+/**
+ * Retire tout userinfo (`user[:pass]@`) d'une URL de remote AVANT toute
+ * exposition (spec § 03, verrou « URLs de remote assainies ») :
+ * - forme URL-scheme (`https://`, `ssh://`, `git://`…) : `scheme://user[:pass]@host/path`
+ *   -> TOUT userinfo est retiré, credentials ou pas (une URL git ne devrait
+ *   jamais en porter — la présence seule est le signal).
+ * - forme scp-like SSH (`[user[:pass]@]host:path`) : TOUT userinfo est retiré
+ *   SAUF le `git@` conventionnel de nos alias (`git@github-perso:owner/repo.git`),
+ *   qui n'est pas un secret (comparaison insensible à la casse). Ça couvre
+ *   aussi bien `user:pass@host:path` (colon avant le '@') qu'un userinfo
+ *   SIMPLE sans colon (`TOKEN@host:path`, ex. un token collé en guise
+ *   d'utilisateur SSH) — les deux formes sont assainies si l'userinfo n'est
+ *   pas exactement `git`.
+ */
+function sanitizeRemoteUrl(raw: string): { sanitized: string; hadCredentials: boolean } {
+  const schemeUserinfo = raw.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^/]*)@(.*)$/);
+  if (schemeUserinfo) {
+    const [, scheme, , rest] = schemeUserinfo;
+    return { sanitized: `${scheme}://${rest}`, hadCredentials: true };
+  }
+  const scpUserinfo = raw.match(/^([^@/]+):([^@/]*)@(.+)$/);
+  if (scpUserinfo) {
+    const [, , , rest] = scpUserinfo;
+    return { sanitized: rest, hadCredentials: true };
+  }
+  // scp-like SSH avec userinfo SIMPLE (sans ':', donc pas capté ci-dessus) :
+  // `userinfo@host:path`. Seul l'userinfo `git` (insensible à la casse) est
+  // l'utilisateur SSH conventionnel de nos alias — tout autre userinfo est
+  // assimilé à un secret et retiré, jamais exposé.
+  const scpSimpleUserinfo = raw.match(/^([^@/]+)@([^/]+:.+)$/);
+  if (scpSimpleUserinfo) {
+    const [, userinfo, rest] = scpSimpleUserinfo;
+    if (userinfo.toLowerCase() === 'git') {
+      return { sanitized: raw, hadCredentials: false };
+    }
+    return { sanitized: rest, hadCredentials: true };
+  }
+  return { sanitized: raw, hadCredentials: false };
+}
+
+interface UrlClassification {
+  scheme: 'ssh-alias' | 'https' | 'ssh-other';
+  aliasDetected: string | null;
+  accountLabel: string | null;
+  expectedAccount: string | null;
+  extraMismatch: GitIdentityMismatch[];
+}
+
+/** Classe une URL de remote DÉJÀ ASSAINIE (jamais l'URL brute). */
+function classifyRemoteUrl(sanitizedUrl: string): UrlClassification {
+  // 1) Forme scheme://host/path — vérifiée EN PREMIER : un scp-like naïf
+  //    ("host:path") matcherait sinon "https" lui-même comme un host.
+  const schemeMatch = sanitizedUrl.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^/]+)\/(.*)$/);
+  if (schemeMatch) {
+    const [, scheme, host, pathPart] = schemeMatch;
+    if (scheme.toLowerCase() === 'https') {
+      const owner = pathPart.split('/')[0] ?? '';
+      const mapped = host.toLowerCase() === 'github.com' && owner ? findAccountByOwner(owner) : null;
+      return {
+        scheme: 'https',
+        aliasDetected: null,
+        accountLabel: null,
+        expectedAccount: mapped ? mapped.account : null,
+        extraMismatch: [
+          {
+            kind: 'https-url',
+            detail: mapped
+              ? `Remote en https:// — protocole interdit sur cette machine ; utiliser l'alias SSH du compte "${mapped.account}".`
+              : `Remote en https:// — protocole interdit sur cette machine, préférer un alias SSH.`,
+          },
+        ],
+      };
+    }
+    return { scheme: 'ssh-other', aliasDetected: null, accountLabel: null, expectedAccount: null, extraMismatch: [] };
+  }
+
+  // 2) Forme scp-like SSH : `[user@]host:path`.
+  const scpMatch = sanitizedUrl.match(/^(?:[^@/]+@)?([^:/]+):(.+)$/);
+  if (scpMatch) {
+    const [, host, pathPart] = scpMatch;
+    const accountInfo = GITHUB_ACCOUNTS_BY_ALIAS[host];
+    if (accountInfo) {
+      const owner = pathPart.split('/')[0] ?? '';
+      const mismatches: GitIdentityMismatch[] = [];
+      if (owner && owner !== accountInfo.owner) {
+        const actualOwnerAccount = findAccountByOwner(owner);
+        mismatches.push({
+          kind: 'owner-alias',
+          detail: actualOwnerAccount
+            ? `Owner "${owner}" appartient au compte "${actualOwnerAccount.account}", pas à l'alias "${host}" (compte "${accountInfo.account}").`
+            : `Owner "${owner}" ne correspond pas au compte attendu par l'alias "${host}" (owner "${accountInfo.owner}").`,
+        });
+      }
+      return {
+        scheme: 'ssh-alias',
+        aliasDetected: host,
+        accountLabel: accountInfo.account,
+        expectedAccount: accountInfo.account,
+        extraMismatch: mismatches,
+      };
+    }
+    return { scheme: 'ssh-other', aliasDetected: null, accountLabel: null, expectedAccount: null, extraMismatch: [] };
+  }
+
+  return { scheme: 'ssh-other', aliasDetected: null, accountLabel: null, expectedAccount: null, extraMismatch: [] };
+}
+
+/** Identité par défaut ("rien à signaler") — utilisée quand aucun remote n'existe. */
+function emptyIdentity(effectiveEmail: string | null): GitIdentity {
+  return {
+    remoteUrl: null,
+    scheme: 'none',
+    aliasDetected: null,
+    accountLabel: null,
+    effectiveEmail,
+    expectedAccount: null,
+    mismatch: [],
+  };
+}
+
+async function listRemoteNames(repoDir: string): Promise<string[]> {
+  const raw = await runGit(repoDir, ['remote']);
+  return raw
+    .split('\n')
+    .map((s) => s.trim())
+    .filter(Boolean);
+}
+
+async function getRemoteUrl(repoDir: string, name: string): Promise<string | null> {
+  try {
+    const raw = (await runGit(repoDir, ['remote', 'get-url', name])).trim();
+    return raw.length > 0 ? raw : null;
+  } catch {
+    return null;
+  }
+}
+
+async function getEffectiveEmail(repoDir: string): Promise<string | null> {
+  try {
+    const raw = (await runGit(repoDir, ['config', 'user.email'])).trim();
+    return raw.length > 0 ? raw : null;
+  } catch {
+    // `git config user.email` sort en échec quand rien n'est configuré —
+    // c'est un état normal (pas une erreur de scan), pas juste une exception.
+    return null;
+  }
+}
+
+/**
+ * Collecte l'identité git d'UN dépôt : 0 remote => `scheme: 'none'` (aucun
+ * mismatch de ce fait) ; >1 remote => `scheme: 'multiple'` (mais l'URL
+ * d'`origin`, si présente, est quand même assainie/classée pour ne pas perdre
+ * le signal). Jamais de fetch réseau — uniquement des lectures locales
+ * (`git remote`, `git remote get-url`, `git config user.email`).
+ */
+async function collectIdentity(repoDir: string): Promise<GitIdentity> {
+  const effectiveEmail = await getEffectiveEmail(repoDir);
+
+  let remoteNames: string[];
+  try {
+    remoteNames = await listRemoteNames(repoDir);
+  } catch {
+    remoteNames = [];
+  }
+
+  if (remoteNames.length === 0) {
+    return emptyIdentity(effectiveEmail);
+  }
+
+  const primaryRemoteName = remoteNames.includes('origin') ? 'origin' : remoteNames[0];
+  const rawUrl = await getRemoteUrl(repoDir, primaryRemoteName);
+
+  if (!rawUrl) {
+    return {
+      ...emptyIdentity(effectiveEmail),
+      scheme: remoteNames.length > 1 ? 'multiple' : 'none',
+    };
+  }
+
+  const { sanitized, hadCredentials } = sanitizeRemoteUrl(rawUrl);
+  const classification = classifyRemoteUrl(sanitized);
+  const mismatch: GitIdentityMismatch[] = [];
+  if (hadCredentials) {
+    mismatch.push({
+      kind: 'credentials-in-url',
+      detail: "Le remote contenait des identifiants embarqués dans l'URL — retirés avant exposition.",
+    });
+  }
+  mismatch.push(...classification.extraMismatch);
+
+  if (classification.expectedAccount) {
+    const expected = findAccountByName(classification.expectedAccount);
+    if (expected && effectiveEmail !== expected.email) {
+      mismatch.push({
+        kind: 'email-alias',
+        detail: `Email de commit "${effectiveEmail ?? '(non défini)'}" différent de l'email attendu pour le compte "${classification.expectedAccount}" ("${expected.email}").`,
+      });
+    }
+  }
+
+  return {
+    remoteUrl: sanitized,
+    scheme: remoteNames.length > 1 ? 'multiple' : classification.scheme,
+    aliasDetected: classification.aliasDetected,
+    accountLabel: classification.accountLabel,
+    effectiveEmail,
+    expectedAccount: classification.expectedAccount,
+    mismatch,
+  };
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Calcul du niveau — hiérarchie stricte, le plus grave gagne (spec § 02)    */
+/* -------------------------------------------------------------------------- */
+
+interface LevelInput {
+  opInProgress: GitOpInProgress | null;
+  branches: BranchTrackInfo[];
+  dirty: { staged: number; unstaged: number; untracked: number; submodules: number };
+  stashCount: number;
+  branchCount: number;
+  currentBranch: string | null;
+}
+
+/** Préfixes usuels de branche de chantier (heuristique d'affichage, LOT 4). */
+const WORK_BRANCH_PREFIX = /^(chantier|chore|feat|feature|fix|loop|refactor)\//;
+
+function computeLevel(input: LevelInput): GitLevel {
+  if (input.opInProgress) return 'blocked';
+
+  // « À risque » : ahead>0 sur N'IMPORTE QUELLE branche locale, OU une branche
+  // sans amont configurée (le travail n'existe potentiellement que sur cette
+  // machine). HEAD détaché est naturellement exclu : refs/heads n'énumère que
+  // des branches NOMMÉES, un détachement n'y apparaît jamais.
+  const hasAheadAnyBranch = input.branches.some((b) => b.ahead > 0);
+  const hasBranchWithoutUpstream = input.branches.some((b) => b.upstream === null);
+  if (hasAheadAnyBranch || hasBranchWithoutUpstream) return 'at-risk';
+
+  const { staged, unstaged, untracked, submodules } = input.dirty;
+  if (staged > 0 || unstaged > 0 || untracked > 0 || submodules > 0) return 'dirty';
+
+  const hasBehind = input.branches.some((b) => b.behind > 0);
+  const isWorkBranch = input.currentBranch !== null && WORK_BRANCH_PREFIX.test(input.currentBranch);
+  if (isWorkBranch || hasBehind || input.stashCount > 0 || input.branchCount >= 3) {
+    return 'noteworthy';
+  }
+
+  return 'clean';
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Scan d'un seul dépôt                                                      */
+/* -------------------------------------------------------------------------- */
+
+function emptyDirty() {
+  return { staged: 0, unstaged: 0, untracked: 0, submodules: 0 };
+}
+
+async function scanRepo(ref: GitRepoRef): Promise<GitRepoSummary> {
+  const { slug, name, path: repoDir } = ref;
+  try {
+    // Les 4 commandes d'UN dépôt tournent en SÉQUENCE (spec § 03) — c'est le
+    // nombre de dépôts EN VOL qui est borné par le sémaphore, pas les
+    // commandes internes à un dépôt.
+    const statusRaw = await runGit(repoDir, [
+      '-c',
+      'core.quotePath=false',
+      '--no-optional-locks',
+      'status',
+      '--porcelain=v2',
+      '--branch',
+      '-z',
+    ]);
+    const status = parseStatusPorcelainV2(statusRaw);
+
+    const refsRaw = await runGit(repoDir, [
+      'for-each-ref',
+      'refs/heads',
+      `--format=${FOR_EACH_REF_FORMAT}`,
+    ]);
+    const branches = parseForEachRef(refsRaw);
+
+    const stashRaw = await runGit(repoDir, ['stash', 'list', '--format=%gd%x09%s%x09%cI']);
+    const stashes = parseStashList(stashRaw);
+
+    const worktreeRaw = await runGit(repoDir, ['worktree', 'list', '--porcelain']);
+    const worktrees = parseWorktreeList(worktreeRaw);
+
+    const opInProgress = await detectOpInProgress(repoDir);
+    const identity = await collectIdentity(repoDir);
+    const refsFreshness = await computeRefsFreshness(repoDir);
+
+    const aheadTotal = branches.reduce((sum, b) => sum + b.ahead, 0);
+    const branchCount = branches.length;
+    const stashCount = stashes.length;
+    const worktreeCount = Math.max(0, worktrees.length - 1);
+
+    const level = computeLevel({
+      opInProgress,
+      branches,
+      dirty: status.dirty,
+      stashCount,
+      branchCount,
+      currentBranch: status.currentBranch,
+    });
+
+    return GitRepoSummarySchema.parse({
+      slug,
+      name,
+      path: repoDir,
+      currentBranch: status.currentBranch,
+      detachedOid: status.detachedOid,
+      initial: status.initial,
+      dirty: status.dirty,
+      aheadTotal,
+      branchCount,
+      stashCount,
+      worktreeCount,
+      opInProgress,
+      level,
+      scanError: null,
+      identity,
+      identityMismatch: identity.mismatch.length > 0,
+      refsFreshness,
+    } satisfies GitRepoSummary);
+  } catch (err) {
+    // Tout échec (execFile, timeout, parsing) => 'unknown' + scanError, JAMAIS
+    // 'clean' par défaut — voir l'en-tête du fichier. Identité et fraîcheur des
+    // refs par défaut (aucun mismatch, `null`/`null`) pour que ce schéma parse
+    // TOUJOURS, même quand le scan de ce dépôt a échoué.

+    // TOUJOURS, même quand le scan de ce dépôt a échoué.
+    const message = err instanceof Error ? err.message : String(err);
+    return GitRepoSummarySchema.parse({
+      slug,
+      name,
+      path: repoDir,
+      currentBranch: null,
+      detachedOid: null,
+      initial: false,
+      dirty: emptyDirty(),
+      aheadTotal: 0,
+      branchCount: 0,
+      stashCount: 0,
+      worktreeCount: 0,
+      opInProgress: null,
+      level: 'unknown',
+      scanError: message.slice(0, 500),
+      identity: emptyIdentity(null),
+      identityMismatch: false,
+      refsFreshness: { lastFetch: null, ageDays: null },
+    } satisfies GitRepoSummary);
+  }
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Détail par dépôt (LOT 2) — fichiers / branches (mergedIntoDefault) /       */
+/*  stashes / worktrees (probablyDone) — consommé par le LOT 3 (route/CLI)    */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * Re-parse la sortie NUL-terminée de `status --porcelain=v2 --branch -z` en
+ * capturant les NOMS de fichiers par état (jamais de contenu). Miroir de
+ * `parseStatusPorcelainV2` (compteurs) mais produit une entrée par fichier —
+ * gardé séparé pour ne pas toucher la fonction déjà testée du LOT 1.
+ */
+function parseStatusPorcelainV2Files(raw: string): GitFileEntry[] {
+  const tokens = raw.split('\0');
+  const files: GitFileEntry[] = [];
+
+  for (let i = 0; i < tokens.length; i++) {
+    const line = tokens[i];
+    if (line.length === 0) continue;
+    if (line.startsWith('#')) continue;
+
+    const marker = line[0];
+
+    if (marker === '?') {
+      files.push({ path: line.slice(2), indexStatus: null, worktreeStatus: null, kind: 'untracked' });
+      continue;
+    }
+    if (marker === '!') continue; // ignored, jamais demandé (pas de --ignored)
+
+    if (marker === 'u') {
+      // `u <XY> <sub> <m1> <m2> <m3> <mW> <h1> <h2> <h3> <path>`
+      const fields = line.split(' ');
+      const xy = fields[1] ?? '';
+      const filePath = fields.slice(10).join(' ');
+      files.push({
+        path: filePath,
+        indexStatus: xy[0] && xy[0] !== '.' ? xy[0] : null,
+        worktreeStatus: xy[1] && xy[1] !== '.' ? xy[1] : null,
+        kind: 'unmerged',
+      });
+      continue;
+    }
+
+    if (marker === '1' || marker === '2') {
+      const fields = line.split(' ');
+      const xy = fields[1] ?? '';
+      const sub = fields[2] ?? '';
+      let filePath: string;
+      if (marker === '2') {
+        // `2 <XY> <sub> <mH> <mI> <mW> <hH> <hI> <X><score> <path>` + un
+        // second token NUL-terminé (l'ancien chemin) consommé sans être exposé.
+        filePath = fields.slice(9).join(' ');
+        i++;
+      } else {
+        // `1 <XY> <sub> <mH> <mI> <mW> <hH> <hI> <path>`
+        filePath = fields.slice(8).join(' ');
+      }
+      const indexStatus = xy[0] && xy[0] !== '.' ? xy[0] : null;
+      const worktreeStatus = xy[1] && xy[1] !== '.' ? xy[1] : null;
+      const kind: GitFileEntry['kind'] = sub.startsWith('S')
+        ? 'submodule'
+        : indexStatus
+          ? 'staged'
+          : 'unstaged';
+      files.push({ path: filePath, indexStatus, worktreeStatus, kind });
+      continue;
+    }
+    // Marqueur inconnu (git plus récent) : ignoré, comme au LOT 1.
+  }
+
+  return files;
+}
+
+/**
+ * Résultat de `computeDefaultBranch()` — sépare volontairement le NOM COURT
+ * (affichage, comparaison `b.name !== defaultBranch.name`) de la RÉVISION
+ * RÉSOLVABLE passée à `git branch --merged` (voir `mergeTarget` ci-dessous) :
+ * ce sont deux besoins différents que la fonction servait mal en n'exposant
+ * qu'un seul nom (fix P1, revue adversariale — voir `computeMergedSet`).
+ */
+interface DefaultBranchInfo {
+  /** Nom court, pour affichage et pour exclure la branche par défaut d'elle-même. */
+  name: string;
+  /** Révision RÉSOLVABLE localement (jamais un simple nom court ambigu) passée à `git branch --merged`. */
+  mergeTarget: string;
+}
+
+/**
+ * Branche par défaut du dépôt : `refs/remotes/origin/HEAD` en priorité
+ * (résolu depuis une ref LOCALE — jamais de fetch réseau), repli sur `main`
+ * puis `master` LOCALE si l'une des deux existe. `null` si rien ne permet de
+ * trancher — `mergedIntoDefault` reste alors non calculable, jamais un crash.
+ *
+ * FIX P1 (revue adversariale) : le chemin PRIMAIRE (symbolic-ref) ne
+ * renvoyait que le NOM COURT (ex. 'main'), sans garantir qu'une branche
+ * LOCALE de ce nom existe — un dépôt où seule `refs/remotes/origin/main`
+ * existe (défaut renommé côté GitHub, clone ancien…) faisait alors échouer
+ * `git branch --merged main` (`fatal: malformed object name main`), et le
+ * `catch` de `computeMergedSet` renvoyait un Set VIDE => TOUTES les branches
+ * ressortaient `mergedIntoDefault=false` (jamais `undefined`), une fausse
+ * tranquillité inversée qui masquait le badge « fusionnée » et cassait
+ * `probablyDone` des worktrees. `mergeTarget` porte désormais une révision
+ * TOUJOURS résolvable : la branche LOCALE `refs/heads/<name>` si elle existe
+ * (donnée la plus fraîche — reflète un merge/commit pas encore repoussé,
+ * cas normal d'un dépôt de travail actif), sinon la ref remote-tracking
+ * `refs/remotes/origin/<name>` elle-même (déjà connue existante puisque
+ * c'est exactement elle que `symbolic-ref` vient de résoudre) — c'est ce
+ * repli qui manquait et causait le bug. Le nom court reste réservé à
+ * l'affichage et à la comparaison `b.name !== defaultBranch.name`.
+ */
+async function computeDefaultBranch(repoDir: string): Promise<DefaultBranchInfo | null> {
+  try {
+    const raw = (await runGit(repoDir, ['symbolic-ref', 'refs/remotes/origin/HEAD'])).trim();
+    const prefix = 'refs/remotes/origin/';
+    if (raw.startsWith(prefix)) {
+      const name = raw.slice(prefix.length);
+      const localRef = `refs/heads/${name}`;
+      try {
+        await runGit(repoDir, ['show-ref', '--verify', '--quiet', localRef]);
+        return { name, mergeTarget: localRef };
+      } catch {
+        // Pas de branche locale de ce nom : repli sur le remote-tracking
+        // (FIX P1) — voir le bloc de commentaire ci-dessus.
+        return { name, mergeTarget: raw };
+      }
+    }
+  } catch {
+    // pas d'origin/HEAD configurée localement — repli ci-dessous.
+  }
+  for (const candidate of ['main', 'master']) {
+    try {
+      const ref = `refs/heads/${candidate}`;
+      await runGit(repoDir, ['show-ref', '--verify', '--quiet', ref]);
+      return { name: candidate, mergeTarget: ref };
+    } catch {
+      // candidate absente, on essaie la suivante
+    }
+  }
+  return null;
+}
+
+/**
+ * `git branch --merged <mergeTarget>` — ensemble des branches locales
+ * fusionnées. `mergeTarget` DOIT être une révision résolvable (voir
+ * `DefaultBranchInfo`), jamais un nom court ambigu.
+ *
+ * FIX P1 : renvoie `null` (pas un Set vide) en cas d'échec — un Set vide est
+ * un résultat LÉGITIME (« aucune branche locale n'est fusionnée »), il ne
+ * doit jamais être confondu avec « le calcul a échoué ». Consommé par
+ * `scanRepoDetail()` : `mergedSet === null` => `mergedIntoDefault` reste
+ * `undefined` pour TOUTES les branches, jamais un `false` définitif fabriqué
+ * à partir d'un échec.
+ */
+async function computeMergedSet(repoDir: string, mergeTarget: string): Promise<Set<string> | null> {
+  try {
+    const raw = await runGit(repoDir, ['branch', '--merged', mergeTarget, '--format=%(refname:short)']);
+    return new Set(
+      raw
+        .split('\n')
+        .map((l) => l.trim())
+        .filter(Boolean),
+    );
+  } catch {
+    return null;
+  }
+}
+
+const WORKTREE_PROBABLY_DONE_AGE_MS = 24 * 60 * 60 * 1000;
+
+/* -------------------------------------------------------------------------- */
+/*  Registre providers in-repo (LOT 8) — lecture SEULE de                     */
+/*  `.claude/.workstation-accounts.json`, jamais écrit par ce service (Q6).   */
+/* -------------------------------------------------------------------------- */
+
+interface ProviderAccountsRead {
+  data: ProviderAccountsFile | null;
+  warning: string | null;
+}
+
+/**
+ * Lit et parse (zod SAFE) le registre providers d'UN dépôt, s'il existe.
+ * Ne lève JAMAIS : fichier absent => `{ data: null, warning: null }` (« non
+ * déclaré », pas une erreur) ; fichier présent mais illisible/mal formé/
+ * invalide (schéma OU forme de secret, voir `parseProviderAccountsFile`) =>
+ * `{ data: null, warning }` — le scan du dépôt continue, jamais un crash
+ * (même contrat que le reste du scanner : un fichier cassé ne doit jamais
+ * faire disparaître silencieusement l'information).
+ */
+async function readProviderAccountsFile(repoDir: string): Promise<ProviderAccountsRead> {
+  const filePath = path.join(repoDir, PROVIDER_ACCOUNTS_RELATIVE_PATH);
+  let raw: string;
+  try {
+    raw = await fs.readFile(filePath, 'utf8');
+  } catch {
+    // Absent (ENOENT) ou illisible (permissions...) : "non déclaré", pas une
+    // erreur à afficher — le geste "déclarer les comptes" (UI) est fait pour ça.
+    return { data: null, warning: null };
+  }
+
+  let json: unknown;
+  try {
+    json = JSON.parse(raw);
+  } catch {
+    return { data: null, warning: `${PROVIDER_ACCOUNTS_RELATIVE_PATH} : JSON invalide, ignoré.` };
+  }
+
+  const parsed = parseProviderAccountsFile(json);
+  if (!parsed.ok) {
+    return { data: null, warning: `${PROVIDER_ACCOUNTS_RELATIVE_PATH} : ${parsed.error}` };
+  }
+  return { data: parsed.data, warning: null };
+}
+
+/**
+ * Croise `expectedGitAccount` (déclaré dans le registre providers) avec le
+ * compte RÉELLEMENT détecté par `collectIdentity()` — spec § 05 « compte
+ * attendu ≠ détecté ». Le compte détecté est `identity.accountLabel` (alias
+ * SSH effectivement utilisé) avec repli sur `identity.expectedAccount`
+ * (déduit d'un owner https, quand aucun alias SSH n'est en jeu) : c'est le
+ * meilleur signal disponible de "quel compte ce dépôt semble utiliser
+ * aujourd'hui". Si aucun des deux n'est résolvable (aucun remote, alias
+ * inconnu…), il n'y a rien d'actionnable à comparer — retourne `null` plutôt
+ * que de fabriquer une alerte bruyante sur une identité indéterminée.
+ */
+function computeExpectedAccountMismatch(
+  declared: ProviderAccountsFile | null,
+  identity: GitIdentity,
+): GitIdentityMismatch | null {
+  if (!declared?.expectedGitAccount) return null;
+  const detectedAccount = identity.accountLabel ?? identity.expectedAccount;
+  if (!detectedAccount) return null;
+  if (detectedAccount === declared.expectedGitAccount) return null;
+  return {
+    kind: 'expected-account',
+    detail: `Compte attendu déclaré ("${declared.expectedGitAccount}") différent du compte détecté ("${detectedAccount}").`,
+  };
+}
+
+/**
+ * Assemble le détail complet d'UN dépôt : résumé (réutilise `scanRepo`) +
+ * fichiers (noms, texte pur) + branches avec `mergedIntoDefault` + stashes +
+ * worktrees avec statut composite `probablyDone` + registre providers
+ * in-repo (LOT 8, lecture seule). Lecture pure, jamais de mutation, jamais de
+ * fetch réseau, jamais d'écriture dans le repo cible (Q6).
+ */
+async function scanRepoDetail(ref: GitRepoRef): Promise<GitRepoDetail> {
+  const { path: repoDir } = ref;
+
+  const summary = await scanRepo(ref);
+
+  let files: GitFileEntry[] = [];
+  try {
+    const statusRaw = await runGit(repoDir, [
+      '-c',
+      'core.quotePath=false',
+      '--no-optional-locks',
+      'status',
+      '--porcelain=v2',
+      '--branch',
+      '-z',
+    ]);
+    files = parseStatusPorcelainV2Files(statusRaw);
+  } catch {
+    files = [];
+  }
+
+  let branchTrack: BranchTrackInfo[] = [];
+  try {
+    const refsRaw = await runGit(repoDir, [
+      'for-each-ref',
+      'refs/heads',
+      `--format=${FOR_EACH_REF_FORMAT}`,
+    ]);
+    branchTrack = parseForEachRef(refsRaw);
+  } catch {
+    branchTrack = [];
+  }
+
+  const defaultBranch = await computeDefaultBranch(repoDir);
+  // FIX P1 : `mergedSet === null` (défaut résolu mais `git branch --merged`
+  // en échec, OU aucun défaut résolvable) => `mergedIntoDefault` reste
+  // `undefined` pour TOUTES les branches ci-dessous, jamais un `false`
+  // fabriqué à partir d'un échec (voir `computeMergedSet`/`computeDefaultBranch`).
+  const mergedSet = defaultBranch ? await computeMergedSet(repoDir, defaultBranch.mergeTarget) : null;
+
+  const branches: GitBranch[] = branchTrack.map((b) => ({
+    name: b.name,
+    upstream: b.upstream,
+    track: { ahead: b.ahead, behind: b.behind, gone: b.gone },
+    lastCommitDate: b.lastCommitDate,
+    mergedIntoDefault:
+      mergedSet && defaultBranch ? mergedSet.has(b.name) && b.name !== defaultBranch.name : undefined,
+  }));
+  const branchByName = new Map(branches.map((b) => [b.name, b] as const));
+
+  let stashes: GitStashEntry[] = [];
+  try {
+    const stashRaw = await runGit(repoDir, ['stash', 'list', '--format=%gd%x09%s%x09%cI']);
+    stashes = parseStashList(stashRaw);
+  } catch {
+    stashes = [];
+  }
+
+  let rawWorktrees: WorktreeInfo[] = [];
+  try {
+    const worktreeRaw = await runGit(repoDir, ['worktree', 'list', '--porcelain']);
+    rawWorktrees = parseWorktreeList(worktreeRaw);
+  } catch {
+    rawWorktrees = [];
+  }
+
+  const now = Date.now();
+  const worktrees: GitWorktreeEntry[] = await Promise.all(
+    rawWorktrees.map(async (wt): Promise<GitWorktreeEntry> => {
+      // Statut composite « probablement terminé » (spec § 07 Q5) — le
+      // `prunable` natif de git ne couvre PAS ce cas : un worktree intact
+      // d'un chip-fixer terminé n'est jamais « prunable » au sens git.
+      // Non calculé pour le worktree PRINCIPAL (ce n'est pas un candidat au
+      // nettoyage).
+      let probablyDone: boolean | undefined;
+      if (!wt.isMain) {
+        probablyDone = false;
+        const branchInfo = wt.branch ? branchByName.get(wt.branch) : undefined;
+        if (branchInfo?.mergedIntoDefault) {
+          const lastCommitMs = branchInfo.lastCommitDate ? Date.parse(branchInfo.lastCommitDate) : NaN;
+          const isOld = Number.isFinite(lastCommitMs) && now - lastCommitMs > WORKTREE_PROBABLY_DONE_AGE_MS;
+          if (isOld) {
+            try {
+              const wtStatusRaw = await runGit(wt.path, [
+                '-c',
+                'core.quotePath=false',
+                '--no-optional-locks',
+                'status',
+                '--porcelain',
+              ]);
+              probablyDone = wtStatusRaw.trim().length === 0;
+            } catch {
+              // Worktree illisible (dossier disparu, gitdir cassé…) : jamais
+              // "probablement terminé" par défaut — cohérent avec le contrat
+              // "jamais de fausse tranquillité" du scanner.
+              probablyDone = false;
+            }
+          }
+        }
+      }
+      return {
+        path: wt.path,
+        branch: wt.branch,
+        detachedOid: wt.detachedOid,
+        isMain: wt.isMain,
+        locked: wt.locked,
+        prunable: wt.prunable,
+        probablyDone,
+      };
+    }),
+  );
+
+  const { data: providerAccounts, warning: providerAccountsWarning } = await readProviderAccountsFile(repoDir);
+
+  // Croisement expectedGitAccount vs identité détectée (LOT 8) — calculé
+  // UNIQUEMENT ici (le résumé, `scanRepo()`, ne lit jamais ce fichier). Le
+  // mismatch, s'il y en a un, s'ajoute à l'identité DU DÉTAIL — jamais en
+  // mutant l'objet `summary.identity` déjà figé.
+  let identity = summary.identity;
+  let identityMismatch = summary.identityMismatch;
+  const expectedAccountMismatch = computeExpectedAccountMismatch(providerAccounts, identity);
+  if (expectedAccountMismatch) {
+    identity = { ...identity, mismatch: [...identity.mismatch, expectedAccountMismatch] };
+    identityMismatch = true;
+  }
+
+  return GitRepoDetailSchema.parse({
+    ...summary,
+    files,
+    branches,
+    stashes,
+    worktrees,
+    identity,
+    identityMismatch,
+    providerAccounts: providerAccounts ?? undefined,
+    providerAccountsWarning: providerAccountsWarning ?? undefined,
+  } satisfies GitRepoDetail);
+}
+
+/**
+ * FIX P2 SCALABILITÉ (revue adversariale) : `scanGitDetail()` n'avait AUCUN
+ * cache — contrairement à `scanGit()` (résumé de la flotte), chaque appel
+ * relançait une passe COMPLÈTE (~7 `execFile` git) sur le dépôt, y compris
+ * pour un simple GET répété rapproché (badge d'en-tête, sélection groupée du
+ * dashboard). Cache mémoire PAR SLUG, même TTL que le résumé
+ * (`SCAN_CACHE_TTL_MS`) + single-flight PAR SLUG — idiome jumeau de
+ * `cache`/`inFlight` ci-dessous, décliné en `Map` puisqu'il y a une entrée
+ * par dépôt plutôt qu'un seul état global.
+ */
+interface DetailCacheEntry {
+  at: number;
+  detail: GitRepoDetail;
+}
+
+const detailCache = new Map<string, DetailCacheEntry>();
+/** Scan de détail déjà EN VOL, par slug — un GET concurrent (refresh ou non)
+ *  le REJOINT plutôt que de déclencher un second passage `execFile` en
+ *  parallèle sur le même dépôt (ex. deux onglets ouverts sur le même projet). */
+const detailInFlight = new Map<string, Promise<GitRepoDetail>>();
+
+/**
+ * Détail complet d'UN dépôt, par slug (ou par chemin absolu déjà résolu par
+ * `listGitRepos()`). Lève si le dépôt est introuvable — au LOT 3, la route
+ * traduit ça en 404 après avoir validé `:slug` contre la liste énumérée
+ * (jamais un `path.join` sur l'input brut).
+ *
+ * `refresh = true` force un rescan en ignorant le cache TTL — même contrat
+ * que `scanGit(refresh)` : c'est la ROUTE qui décide si `?refresh=1` est
+ * ACCORDÉ (cooldown ~2s partagé avec `/status`, voir `server/routes/git.ts`),
+ * jamais ce service. Single-flight : un scan déjà en cours pour ce slug est
+ * PARTAGÉ, `refresh` ou non — un `refresh` ne peut donc pas dédoubler le
+ * travail d'un scan déjà en vol pour le même dépôt.
+ */
+export async function scanGitDetail(slugOrPath: string, refresh = false): Promise<GitRepoDetail> {
+  const refs = await listGitRepos();
+  const ref = refs.find((r) => r.slug === slugOrPath) ?? refs.find((r) => r.path === slugOrPath);
+  if (!ref) {
+    throw new Error(`Dépôt git introuvable : ${slugOrPath}`);
+  }
+
+  const cacheKey = ref.slug;
+
+  if (!refresh) {
+    const cached = detailCache.get(cacheKey);
+    if (cached && Date.now() - cached.at < SCAN_CACHE_TTL_MS) {
+      return cached.detail;
+    }
+  }
+
+  const existingInFlight = detailInFlight.get(cacheKey);
+  if (existingInFlight) {
+    return existingInFlight;
+  }
+
+  const run = (async () => {
+    const detail = await scanRepoDetail(ref);
+    detailCache.set(cacheKey, { at: Date.now(), detail });
+    return detail;
+  })();
+
+  detailInFlight.set(cacheKey, run);
+  try {
+    return await run;
+  } finally {
+    detailInFlight.delete(cacheKey);
+  }
+}
+
+/* -------------------------------------------------------------------------- */
+/*  API publique — scan cache (30s) + single-flight                          */
+/* -------------------------------------------------------------------------- */
+
+interface CacheEntry {
+  at: number;
+  repos: GitRepoSummary[];
+}
+
+let cache: CacheEntry | null = null;
+let inFlight: Promise<GitRepoSummary[]> | null = null;
+
+/**
+ * Garde de génération anti-clobber (RACE 1, revue adversariale post-LOT 7) :
+ * compteur monotone module-level, incrémenté à CHAQUE mutation du cache
+ * effectuée par `rescanRepo()` (jamais par `scanGit()` lui-même). `scanGit()`
+ * capture sa valeur AVANT de lancer son scan (`startGen`, dans `run()`
+ * ci-dessous) ; toute mutation de `rescanRepo()` survenue PENDANT ce scan
+ * porte donc un numéro strictement supérieur à `startGen` — c'est ce que
+ * `mergeScanResults()` détecte pour ne JAMAIS écraser une mise à jour ciblée
+ * plus fraîche que le scan complet en cours.
+ */
+let cacheGen = 0;
+/** Dernière génération de mutation cache PAR SLUG, écrite uniquement par `rescanRepo()`. */
+const perSlugRescanGen = new Map<string, number>();
+
+/**
+ * Fusion PURE (donc testable indépendamment de tout interleaving temporel
+ * réel) entre le résultat d'un scan complet (`results`) et le cache COURANT
+ * (`currentCacheRepos`, lu juste avant l'écriture finale de `scanGit()`) —
+ * voir `perSlugRescanGen`/`cacheGen` ci-dessus. Pour CHAQUE dépôt `r` de
+ * `results`, trois cas selon `rg = perSlugRescanGenerations.get(r.slug) ?? 0` :
+ *
+ * 1. `rg > startGen` ET `currentCacheRepos` contient encore `r.slug` :
+ *    `rescanRepo()` a mis à jour ce dépôt PENDANT le scan — l'entrée du
+ *    cache courant (plus fraîche) est retenue à la place du résultat du scan.
+ * 2. `rg > startGen` ET `currentCacheRepos` NE contient PLUS `r.slug` :
+ *    `rescanRepo()` a SUPPRIMÉ ce dépôt pendant la fenêtre de scan (repo
+ *    disparu du disque) — le résultat (périmé) du scan n'est PAS repoussé,
+ *    sous peine de faire réapparaître une ligne fantôme (souvent
+ *    `level: 'unknown'`/`scanError`) pour un dépôt qui n'existe plus.
+ * 3. `rg <= startGen` (aucune mutation concurrente, ou survenue AVANT le
+ *    départ du scan) : le résultat du scan fait foi tel quel — couvre aussi
+ *    un dépôt nouvellement apparu et jamais rescanné (`rg` implicite à 0).
+ *
+ * Pas de court-circuit sur un `currentCacheRepos` vide/absent : avec une
+ * `Map` vide construite à partir de `[]`/`null`, le cas 1 ne peut jamais
+ * matcher (aucune entrée à retrouver) et tout `r` retombe naturellement sur
+ * le cas 2 (`rg > startGen`, dépôt absent → drop) ou 3 (`rg <= startGen`,
+ * scan fait foi) — correct aussi bien pour le tout premier scan (cache
+ * jamais initialisé, `perSlugRescanGen` vide, tout est cas 3) que pour un
+ * cache redevenu vide après suppression du dernier dépôt suivi.
+ */
+export function mergeScanResults(
+  results: GitRepoSummary[],
+  currentCacheRepos: GitRepoSummary[] | null,
+  perSlugRescanGenerations: ReadonlyMap<string, number>,
+  startGen: number,
+): GitRepoSummary[] {
+  const currentBySlug = new Map((currentCacheRepos ?? []).map((r) => [r.slug, r] as const));
+  const merged: GitRepoSummary[] = [];
+  for (const result of results) {
+    const gen = perSlugRescanGenerations.get(result.slug) ?? 0;
+    if (gen > startGen) {
+      const fresher = currentBySlug.get(result.slug);
+      if (fresher) {
+        merged.push(fresher);
+      }
+      // Sinon : rescanRepo() a supprimé ce dépôt pendant la fenêtre du scan —
+      // ne PAS repousser le résultat périmé (pas de résurrection fantôme).
+      continue;
+    }
+    merged.push(result);
+  }
+  return merged;
+}
+
+/**
+ * Scanne tous les dépôts sous `projectsRoot()`. Cache mémoire TTL ~30s
+ * (`SCAN_CACHE_TTL_MS`) ; `refresh=true` force un rescan en ignorant le cache.
+ * Single-flight : un scan déjà en cours est PARTAGÉ (jamais dupliqué) par tout
+ * appelant concurrent, `refresh` ou non — le bouton refresh (LOT 3/4) ne peut
+ * donc pas devenir un déni de service auto-infligé.
+ *
+ * RACE 1 (revue adversariale) : ce scan capture `startGen` avant de partir,
+ * puis fusionne ses résultats avec le cache courant via `mergeScanResults()`
+ * avant d'écrire — un `rescanRepo(X)` concurrent qui a mis à jour le cache
+ * PENDANT ce scan n'est donc jamais écrasé par le résultat (plus ancien) de
+ * ce scan pour X.
+ */
+export async function scanGit(refresh = false): Promise<GitRepoSummary[]> {
+  if (!refresh && cache && Date.now() - cache.at < SCAN_CACHE_TTL_MS) {
+    return cache.repos;
+  }
+  if (inFlight) {
+    return inFlight;
+  }
+
+  const run = (async () => {
+    const startGen = cacheGen;
+    const repos = await listGitRepos();
+    const semaphore = new Semaphore(MAX_CONCURRENT_SCANS);
+    const results = await Promise.all(repos.map((r) => semaphore.run(() => scanRepo(r))));
+    const merged = mergeScanResults(results, cache?.repos ?? null, perSlugRescanGen, startGen);
+    cache = { at: Date.now(), repos: merged };
+    return merged;
+  })();
+
+  inFlight = run;
+  try {
+    return await run;
+  } finally {
+    inFlight = null;
+  }
+}
+
+/**
+ * Re-scanne UN SEUL dépôt (résolu via `listGitRepos()` — jamais un chemin
+ * brut) et remplace SON ENTRÉE dans le cache global de `scanGit()`. C'est
+ * l'appel que fait le watcher (LOT 7, `gitWatcher.ts`) AVANT de publier
+ * `git-changed {slug}` : le client qui refetch juste après l'événement doit
+ * lire un état déjà frais — jamais un cache encore chaud (spec § 03, "le
+ * watcher rescanne et met le cache à jour avant de publier").
+ *
+ * - Dépôt disparu (plus de `.git` sous `projectsRoot()`) : `null`, et son
+ *   entrée est RETIRÉE du cache (pas d'entrée fantôme qui resterait "clean").
+ * - Dépôt présent dans `listGitRepos()` mais absent du cache (repo tout juste
+ *   apparu, ou jamais scanné) : son résumé est AJOUTÉ au cache s'il existe
+ *   déjà (ne le crée pas s'il est vide — un cache absent est déjà couvert par
+ *   le prochain `scanGit()`, qui fera de toute façon un scan complet).
+ * - Cache vide (`null`, jamais scanné) : no-op sur le cache — un état partiel
+ *   à une seule entrée n'a pas de sens tant qu'aucun scan complet n'a eu lieu ;
+ *   le résumé recalculé est quand même RETOURNÉ (le watcher publie l'événement
+ *   dans tous les cas, un futur `scanGit()` fera le scan complet).
+ *
+ * RACE 1 (revue adversariale) : CHAQUE mutation RÉELLE du cache ci-dessous
+ * (branche suppression ET branche mise à jour) incrémente `cacheGen` et
+ * enregistre ce numéro dans `perSlugRescanGen` pour ce slug — c'est ce qui
+ * permet à `scanGit()` de détecter qu'un scan complet en vol est devenu
+ * périmé pour CE slug et de ne pas écraser cette mise à jour à la fin de son
+ * propre `run()` (voir `mergeScanResults()`).
+ *
+ * FIX P2 SCALABILITÉ : invalide AUSSI le cache de DÉTAIL de ce slug
+ * (`detailCache`, ajouté pour `scanGitDetail()`) — sans ça, un client qui
+ * refetch `/api/git/:slug` juste après l'événement `git-changed` (sans
+ * `?refresh=1`, cas normal du réveil temps réel côté `useGitStatus`)
+ * pourrait se voir servir un DÉTAIL resté chaud depuis avant le changement,
+ * alors que le RÉSUMÉ (ci-dessus) est déjà frais — la même garantie "jamais
+ * un cache encore chaud" doit couvrir les deux caches.
+ */
+export async function rescanRepo(slug: string): Promise<GitRepoSummary | null> {
+  const refs = await listGitRepos();
+  const ref = refs.find((r) => r.slug === slug);
+  detailCache.delete(slug);
+
+  if (!ref) {
+    if (cache) {
+      cache = { at: cache.at, repos: cache.repos.filter((r) => r.slug !== slug) };
+      perSlugRescanGen.set(slug, ++cacheGen);
+    }
+    return null;
+  }
+
+  const summary = await scanRepo(ref);
+
+  if (cache) {
+    const idx = cache.repos.findIndex((r) => r.slug === slug);
+    const nextRepos =
+      idx === -1
+        ? [...cache.repos, summary]
+        : cache.repos.map((r, i) => (i === idx ? summary : r));

+        : cache.repos.map((r, i) => (i === idx ? summary : r));
+    cache = { at: cache.at, repos: nextRepos };
+    perSlugRescanGen.set(slug, ++cacheGen);
+  }
+
+  return summary;
+}

