@@ -0,0 +1,370 @@
+/**
+ * Observatoire Git — watchers temps réel (LOT 7).
+ *
+ * Un commit fait par une session Claude doit apparaître TOUT SEUL dans
+ * l'observatoire, sans clic. Par dépôt (`listGitRepos()`), on surveille
+ * `<gitdir>/HEAD`, `<gitdir>/index`, `<gitdir>/refs/` (récursif) et
+ * `<gitdir>/worktrees/` (récursif) — sinon un fetch, une suppression de
+ * branche ou un worktree ajouté/retiré sont des angles morts (spec § 03).
+ * `<gitdir>` est résolu via `resolveGitDir()` (`gitScanner.ts`) : `.git` est
+ * un DOSSIER pour un dépôt principal, mais un FICHIER `gitdir: <chemin>` pour
+ * un worktree lié — les deux cas sont gérés sans crash.
+ *
+ * ORDRE STRICT à chaque déclenchement (spec § 03, non négociable) :
+ *   1. `rescanRepo(slug)` (met à jour le cache global de `scanGit()`)
+ *   2. PUIS `publish({ type: 'git-changed', slug })`
+ * Jamais l'inverse — sinon un client qui refetch juste après l'événement lit
+ * un cache encore chaud et le badge ne bouge pas ("temps réel cosmétique").
+ *
+ * Debounce 500 ms PAR DÉPÔT (pas par fichier) avec un PLAFOND max-wait de
+ * 2,5 s : un rebase qui enchaîne les écritures sur HEAD/index/refs ne doit
+ * jamais geler l'affichage au-delà de ce plafond.
+ *
+ * Cycle de vie réconcilié à chaque scan (`reconcile()`, rejoué périodiquement
+ * ET au démarrage) : watchers créés pour les nouveaux dépôts, `.close()`
+ * EXPLICITE pour les dépôts disparus — le service launchd tourne des mois
+ * sans redémarrer, aucun handle ne doit s'accumuler. Un target absent au
+ * moment de la tentative (ex. `.git/worktrees` inexistant tant qu'aucun
+ * worktree lié n'a été créé) est retenté au prochain `reconcile()` — jamais
+ * une exception qui remonte.
+ *
+ * GARDE DEV (spec § 03) : en mode dev (`WORKSTATION_DATA_ROOT` posé), prod
+ * (5179) et dev (5180) scannent EXACTEMENT les mêmes dépôts sous
+ * `PROJECTS_ROOT` — deux jeux de watchers dupliqueraient le travail pour rien.
+ * `startGitWatching()` est donc un NO-OP en dev, sauf activation explicite via
+ * `WORKSTATION_GIT_WATCH=1`.
+ */
+import { watch, type FSWatcher } from 'node:fs';
+import path from 'node:path';
+
+import { listGitRepos, rescanRepo, resolveGitDir, type GitRepoRef } from './gitScanner';
+import { publish } from './eventBus';
+
+/** Coalesce les rafales d'écritures d'UN dépôt (spec § 03 : "500ms"). */
+const DEFAULT_DEBOUNCE_MS = 500;
+/** Plafond au-delà duquel on émet quand même, même sous rafale continue. */
+const DEFAULT_MAX_WAIT_MS = 2_500;
+/** Intervalle de réconciliation périodique (nouveaux dépôts / dépôts disparus). */
+const DEFAULT_RECONCILE_MS = 15_000;
+
+/**
+ * Valeurs EFFECTIVES des trois constantes ci-dessus — mutables uniquement pour
+ * que `startGitWatching({ debounceMs, maxWaitMs, reconcileMs })` (test-only ;
+ * la prod n'appelle jamais avec ces overrides) puisse les accélérer sans
+ * attendre de vrais délais de 500ms/2,5s/15s dans les tests du LOT 7.
+ * Réinitialisées à leur défaut par `stopGitWatching()` pour qu'un test suivant
+ * (ou un futur démarrage prod) ne reste jamais sur un override oublié.
+ */
+let debounceMs = DEFAULT_DEBOUNCE_MS;
+let maxWaitMs = DEFAULT_MAX_WAIT_MS;
+
+/* -------------------------------------------------------------------------- */
+/*  État module-level — un seul jeu de watchers par process serveur           */
+/* -------------------------------------------------------------------------- */
+
+interface RepoWatch {
+  slug: string;
+  /**
+   * Watch NON récursif sur `<gitdir>` lui-même — capture les écritures
+   * directes de HEAD/index (et voisins : `packed-refs`, `ORIG_HEAD`…).
+   * PAS de filtre par basename : git écrit HEAD/index via lock-puis-rename
+   * (`index.lock` -> `index`), et le nom rapporté par `fs.watch` pour
+   * l'événement de rename est celui du LOCK FILE, pas de la destination
+   * finale (vérifié empiriquement, macOS/FSEvents, git 2.50) — un filtre
+   * strict sur `'HEAD' | 'index'` raterait silencieusement l'événement.
+   * Toute écriture top-level du gitdir déclenche donc le debounce ; le coût
+   * d'un faux positif occasionnel (ex. `config` édité à la main) est un
+   * rescan de plus, jamais un événement manqué.
+   */
+  headIndexWatcher: FSWatcher | null;
+  /** Watch récursif sur `<gitdir>/refs`. */
+  refsWatcher: FSWatcher | null;
+  /** Watch récursif sur `<gitdir>/worktrees` (absent tant qu'aucun worktree lié). */
+  worktreesWatcher: FSWatcher | null;
+}
+
+const repoWatches = new Map<string, RepoWatch>();
+const debounceTimers = new Map<string, ReturnType<typeof setTimeout>>();
+const maxWaitTimers = new Map<string, ReturnType<typeof setTimeout>>();
+
+let reconcileTimer: ReturnType<typeof setInterval> | null = null;
+let started = false;
+let stopped = true;
+
+/* -------------------------------------------------------------------------- */
+/*  Watch d'une cible unique — jamais de crash si le chemin n'existe pas      */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * Ouvre un `fs.watch` sur `target`, best-effort : un chemin absent ou une
+ * erreur de plateforme (watch récursif non supporté) est capturée — `null` en
+ * retour, retenté au prochain `reconcile()`. `onError` réarme le slot à `null`
+ * pour qu'une erreur en cours de vie (dossier supprimé sous le watcher) soit
+ * elle aussi retentée, pas juste ignorée pour toujours.
+ *
+ * PAS de filtre par nom de fichier : git écrit ses refs via lock-puis-rename
+ * (`index.lock` -> `index`, `heads/main.lock` -> `heads/main`…) et le nom
+ * rapporté par `fs.watch` pour l'événement de rename est celui du LOCK FILE
+ * (vérifié empiriquement, macOS/FSEvents) — filtrer sur le nom final
+ * raterait silencieusement l'événement. On déclenche donc sur TOUTE écriture
+ * dans la cible surveillée ; le debounce par dépôt absorbe le bruit.
+ */
+function openWatch(
+  target: string,
+  recursive: boolean,
+  onFire: () => void,
+  onError: () => void,
+): FSWatcher | null {
+  let watcher: FSWatcher;
+  try {
+    watcher = watch(target, { recursive });
+  } catch {
+    return null;
+  }
+
+  const handler = () => onFire();
+  watcher.on('change', handler);
+  watcher.on('rename', handler);
+  watcher.on('error', (err) => {
+    // eslint-disable-next-line no-console
+    console.warn(`[workstation] git watcher error (${target}): ${String(err)}`);
+    try {
+      watcher.close();
+    } catch {
+      // déjà fermé — sans conséquence.
+    }
+    onError();
+  });
+
+  return watcher;
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Debounce PAR DÉPÔT avec plafond max-wait                                  */
+/* -------------------------------------------------------------------------- */
+
+function scheduleRepoChange(slug: string): void {
+  if (stopped) return;
+
+  // Premier événement d'une rafale : arme le plafond (une seule fois par rafale).
+  if (!maxWaitTimers.has(slug)) {
+    maxWaitTimers.set(
+      slug,
+      setTimeout(() => {
+        maxWaitTimers.delete(slug);
+        const debounce = debounceTimers.get(slug);
+        if (debounce) {
+          clearTimeout(debounce);
+          debounceTimers.delete(slug);
+        }
+        void fireRepoChange(slug);
+      }, maxWaitMs),
+    );
+  }
+
+  // Chaque événement repousse le debounce — sauf si le plafond tranche avant.
+  const existing = debounceTimers.get(slug);
+  if (existing) clearTimeout(existing);
+  debounceTimers.set(
+    slug,
+    setTimeout(() => {
+      debounceTimers.delete(slug);
+      const maxWait = maxWaitTimers.get(slug);
+      if (maxWait) {
+        clearTimeout(maxWait);
+        maxWaitTimers.delete(slug);
+      }
+      void fireRepoChange(slug);
+    }, debounceMs),
+  );
+}
+
+/**
+ * ORDRE STRICT (spec § 03) : rescan + mise à jour du cache AVANT publication.
+ * Un dépôt disparu entre la programmation et le déclenchement (rescanRepo
+ * renvoie `null`) publie quand même — le client refetch, constate le 404 (ou
+ * l'absence dans /status) et retire la ligne lui-même ; ce watcher n'a pas à
+ * décider de l'affichage.
+ */
+async function fireRepoChange(slug: string): Promise<void> {
+  if (stopped) return;
+  try {
+    await rescanRepo(slug);
+  } catch (err) {
+    // eslint-disable-next-line no-console
+    console.warn(`[workstation] git rescan failed for '${slug}' (non-fatal): ${String(err)}`);
+  }
+  if (stopped) return;
+  publish({ type: 'git-changed', slug });
+}
+
+/* -------------------------------------------------------------------------- */
+/*  Réconciliation : un dépôt <-> ses watchers                                */
+/* -------------------------------------------------------------------------- */
+
+async function ensureRepoWatch(ref: GitRepoRef): Promise<void> {
+  if (stopped) return;
+
+  const gitDir = await resolveGitDir(ref.path);
+  if (!gitDir) return; // `.git` introuvable/illisible pour l'instant — retenté au prochain reconcile.
+
+  let rw = repoWatches.get(ref.slug);
+  if (!rw) {
+    rw = { slug: ref.slug, headIndexWatcher: null, refsWatcher: null, worktreesWatcher: null };
+    repoWatches.set(ref.slug, rw);
+  }
+  const current = rw;
+  const onFire = () => scheduleRepoChange(ref.slug);
+
+  if (!current.headIndexWatcher) {
+    current.headIndexWatcher = openWatch(gitDir, false, onFire, () => {
+      current.headIndexWatcher = null;
+    });
+  }
+  if (!current.refsWatcher) {
+    current.refsWatcher = openWatch(path.join(gitDir, 'refs'), true, onFire, () => {
+      current.refsWatcher = null;
+    });
+  }
+  if (!current.worktreesWatcher) {
+    current.worktreesWatcher = openWatch(path.join(gitDir, 'worktrees'), true, onFire, () => {
+      current.worktreesWatcher = null;
+    });
+  }
+}
+
+function closeRepoWatch(rw: RepoWatch): void {
+  rw.headIndexWatcher?.close();
+  rw.refsWatcher?.close();
+  rw.worktreesWatcher?.close();
+}
+
+/**
+ * Resynchronise les watchers avec la liste RÉELLE des dépôts sous
+ * `projectsRoot()` : ferme `.close()` les dépôts disparus (et leurs timers en
+ * attente — un dépôt supprimé ne doit pas laisser une rafale en vol tenter de
+ * le rescanner), (ré)ouvre les cibles manquantes des dépôts existants (nouveau
+ * dépôt, ou target retenté après une erreur/absence précédente).
+ *
+ * EXPORTÉE (LOT 7, lacune de test comblée) : la réconciliation périodique
+ * (`RECONCILE_MS` par défaut 15s) n'était pas testable en pratique — un test
+ * peut désormais appeler `reconcile()` directement, de façon déterministe,
+ * pour prouver qu'un dépôt apparu/disparu sous `projectsRoot()` est bien
+ * (re)watché sans attendre un vrai tick de 15s.
+ */
+export async function reconcile(): Promise<void> {
+  if (stopped) return;
+
+  let refs: GitRepoRef[];
+  try {
+    refs = await listGitRepos();
+  } catch {
+    return; // PROJECTS_ROOT temporairement illisible — retenté au prochain tick.
+  }
+  const wantedSlugs = new Set(refs.map((r) => r.slug));
+
+  for (const [slug, rw] of repoWatches) {
+    if (!wantedSlugs.has(slug)) {
+      closeRepoWatch(rw);
+      repoWatches.delete(slug);
+      const debounce = debounceTimers.get(slug);
+      if (debounce) {
+        clearTimeout(debounce);
+        debounceTimers.delete(slug);
+      }
+      const maxWait = maxWaitTimers.get(slug);
+      if (maxWait) {
+        clearTimeout(maxWait);
+        maxWaitTimers.delete(slug);
+      }
+    }
+  }
+
+  for (const ref of refs) {
+    // eslint-disable-next-line no-await-in-loop -- ~21 dépôts, résolution de gitdir déjà bornée (fs.lstat/readFile), simplicité > micro-parallélisme (même choix que gitScanner pour les opérations séquentielles fixes).
+    await ensureRepoWatch(ref);
+  }
+}
+
+/* -------------------------------------------------------------------------- */
+/*  API publique                                                              */
+/* -------------------------------------------------------------------------- */
+
+/** Overrides test-only des trois délais — jamais fournis en prod (voir `debounceMs`/`maxWaitMs` ci-dessus). */
+export interface GitWatchOptions {
+  /** Override de `RECONCILE_MS` (défaut 15s) — accélère la réconciliation périodique en test. */
+  reconcileMs?: number;
+  /** Override du debounce par dépôt (défaut 500ms). */
+  debounceMs?: number;
+  /** Override du plafond max-wait (défaut 2,5s). */
+  maxWaitMs?: number;
+}
+
+/**
+ * Démarre les watchers .git de tous les dépôts sous `projectsRoot()`.
+ * Idempotent (un second appel pendant que les watchers tournent est un no-op
+ * — `options` est alors IGNORÉ, comme le reste de la configuration).
+ *
+ * GARDE DEV : si `WORKSTATION_DATA_ROOT` est posé (mode dev — voir
+ * `config.ts:dataRoot()`) ET que `WORKSTATION_GIT_WATCH` n'est PAS `'1'`,
+ * cet appel est un NO-OP explicite (log) : la prod (sans `WORKSTATION_DATA_ROOT`)
+ * démarre toujours ; le dev ne démarre que sur activation volontaire, pour ne
+ * jamais dupliquer les watchers sur les mêmes ~21 dépôts que la prod.
+ *
+ * `options` (LOT 7, lacune de test comblée) : PARAMÈTRE TEST-ONLY — la prod
+ * n'appelle jamais `startGitWatching()` avec des overrides, seuls les tests
+ * accélèrent `debounceMs`/`maxWaitMs`/`reconcileMs` pour rester déterministes
+ * sans dépendre de vrais délais de plusieurs secondes.
+ */
+export async function startGitWatching(options: GitWatchOptions = {}): Promise<void> {
+  if (process.env.WORKSTATION_DATA_ROOT && process.env.WORKSTATION_GIT_WATCH !== '1') {
+    // eslint-disable-next-line no-console
+    console.log(
+      "[workstation] git watchers désactivés en dev (mêmes dépôts que la prod) — WORKSTATION_GIT_WATCH=1 pour forcer",
+    );
+    return;
+  }
+  if (started) return;
+  started = true;
+  stopped = false;
+
+  debounceMs = options.debounceMs ?? DEFAULT_DEBOUNCE_MS;
+  maxWaitMs = options.maxWaitMs ?? DEFAULT_MAX_WAIT_MS;
+  const reconcileMs = options.reconcileMs ?? DEFAULT_RECONCILE_MS;
+
+  await reconcile();
+  reconcileTimer = setInterval(() => void reconcile(), reconcileMs);
+  // Un setInterval de fond ne doit jamais empêcher le process de sortir
+  // (ex. `bun test`) s'il oublie d'appeler stopGitWatching().
+  reconcileTimer.unref?.();
+}
+
+/**
+ * Arrête TOUT proprement : timers de réconciliation, debounce et max-wait en
+ * attente, et `.close()` explicite de chaque watcher ouvert — aucun handle
+ * orphelin (le service launchd tourne des mois, un leak s'accumulerait).
+ * Idempotent — sûr à appeler même si les watchers n'ont jamais démarré (garde
+ * dev active, ou double arrêt). Réinitialise aussi les overrides test-only de
+ * `startGitWatching(options)` à leurs défauts, pour qu'un prochain démarrage
+ * (test suivant, ou un futur démarrage prod) ne reste jamais sur une valeur
+ * accélérée oubliée.
+ */
+export function stopGitWatching(): void {
+  stopped = true;
+  started = false;
+
+  if (reconcileTimer) {
+    clearInterval(reconcileTimer);
+    reconcileTimer = null;
+  }
+  for (const timer of debounceTimers.values()) clearTimeout(timer);
+  debounceTimers.clear();
+  for (const timer of maxWaitTimers.values()) clearTimeout(timer);
+  maxWaitTimers.clear();
+
+  for (const rw of repoWatches.values()) closeRepoWatch(rw);
+  repoWatches.clear();
+
+  debounceMs = DEFAULT_DEBOUNCE_MS;
+  maxWaitMs = DEFAULT_MAX_WAIT_MS;
+}

diff --git a/server/routes/git.ts b/server/routes/git.ts
new file mode 100644
index 0000000..dc42283
--- /dev/null
+++ b/server/routes/git.ts
@@ -0,0 +1,120 @@
+import fs from 'node:fs/promises';
+import path from 'node:path';
+
+import { Router } from 'express';
+
+import { scanGit, scanGitDetail, listGitRepos } from '../services/gitScanner';
+import { isSafeSegment } from '../services/slug';
+import { projectsRoot } from '../config';
+
+/**
+ * Observatoire Git — routes HTTP (LOT 3).
+ *
+ * `GET /status` (résumé de tous les dépôts) et `GET /:slug` (détail d'un
+ * dépôt) — lecture pure, aucune mutation. Verrous sécurité (spec § 03,
+ * validation ultracode — tunnel Cloudflare oblige) :
+ *
+ * - `:slug` validé par `isSafeSegment` PUIS résolu UNIQUEMENT contre la liste
+ *   énumérée par `listGitRepos()` — jamais un `path.join` sur l'input brut.
+ * - Containment défensif AVANT tout execFile (`scanGitDetail`) : le chemin
+ *   résolu doit rester, après `fs.realpath`, sous `fs.realpath(projectsRoot())`
+ *   — un symlink glissé entre l'énumération et cette requête ne peut donc pas
+ *   faire sortir un scan de `PROJECTS_ROOT` (même idiome que
+ *   `skillScanner.skillDirFor`).
+ * - Le PATH résolu (issu de `listGitRepos()`), jamais l'input brut, est celui
+ *   passé à `scanGitDetail`.
+ *
+ * `?refresh=1` : single-flight déjà assuré par `scanGit()` (un scan en cours
+ * est partagé, jamais dupliqué) + un cooldown ~2s MODULE-LEVEL, partagé entre
+ * les deux routes — le bouton refresh (LOT 4/5) ne peut donc pas devenir un
+ * déni de service auto-infligé, qu'il tape `/status` ou `/:slug` en rafale.
+ * Sous cooldown : aucune passe forcée, `throttled: true` dans la réponse.
+ */
+export const gitRouter = Router();
+
+/** Cooldown minimal entre deux refresh forcés — spec § 03 "~2-3s", milieu de fourchette. */
+const REFRESH_COOLDOWN_MS = 2_000;
+
+/** Timestamp du dernier refresh forcé ACCORDÉ, partagé entre /status et /:slug. */
+let lastRefreshAt = 0;
+
+/**
+ * Décide si CETTE requête (qui a demandé `?refresh=1`) obtient le refresh ou
+ * est throttlée — et met à jour `lastRefreshAt` quand elle l'obtient. Centralisé
+ * ici pour que /status et /:slug partagent EXACTEMENT la même horloge de
+ * cooldown (spec : "un timestamp module-level du dernier refresh").
+ */
+function claimRefresh(wantsRefresh: boolean): { granted: boolean; throttled: boolean } {
+  if (!wantsRefresh) return { granted: false, throttled: false };
+  const now = Date.now();
+  if (now - lastRefreshAt < REFRESH_COOLDOWN_MS) {
+    return { granted: false, throttled: true };
+  }
+  lastRefreshAt = now;
+  return { granted: true, throttled: false };
+}
+
+/* -------------------------------------------------------------------------- */
+/*  GET /status — résumé de tous les dépôts (ordre déclaré AVANT /:slug —      */
+/*  sinon path-to-regexp capturerait 'status' comme un slug)                  */
+/* -------------------------------------------------------------------------- */
+
+gitRouter.get('/status', async (req, res) => {
+  try {
+    const { granted, throttled } = claimRefresh(req.query.refresh === '1');
+    const repos = await scanGit(granted);
+    res.json(throttled ? { repos, throttled: true } : { repos });
+  } catch (err) {
+    res.status(500).json({ error: 'Failed to scan git repos', detail: String(err) });
+  }
+});
+
+/* -------------------------------------------------------------------------- */
+/*  GET /:slug — détail d'un dépôt                                            */
+/* -------------------------------------------------------------------------- */
+
+gitRouter.get('/:slug', async (req, res) => {
+  const { slug } = req.params;
+  if (!isSafeSegment(slug)) {
+    res.status(400).json({ error: 'Invalid slug' });
+    return;
+  }
+
+  try {
+    // Résolution UNIQUEMENT contre la liste énumérée — jamais path.join(input).
+    const refs = await listGitRepos();
+    const ref = refs.find((r) => r.slug === slug);
+    if (!ref) {
+      res.status(404).json({ error: 'Repo not found' });
+      return;
+    }
+
+    // Containment défensif avant tout execFile — voir doc du module.
+    let realRoot: string;
+    let realRepoPath: string;
+    try {
+      realRoot = await fs.realpath(projectsRoot());
+      realRepoPath = await fs.realpath(ref.path);
+    } catch {
+      res.status(404).json({ error: 'Repo not found' });
+      return;
+    }
+    if (realRepoPath !== realRoot && !realRepoPath.startsWith(realRoot + path.sep)) {
+      res.status(404).json({ error: 'Repo not found' });
+      return;
+    }
+
+    // FIX P2 SCALABILITÉ (revue adversariale) : `scanGitDetail()` a désormais
+    // son propre cache TTL + single-flight PAR SLUG (idiome jumeau de
+    // `scanGit()`) — `granted` décide si CETTE requête bypasse ce cache
+    // (rescan forcé), `throttled` informe le client que le refresh EXPLICITE
+    // demandé n'a pas été "accordé" (cooldown ~2s partagé avec `/status`).
+    const { granted, throttled } = claimRefresh(req.query.refresh === '1');
+
+    // PATH résolu (issu de listGitRepos), jamais l'input brut `slug`.
+    const detailResult = await scanGitDetail(ref.path, granted);
+    res.json(throttled ? { ...detailResult, throttled: true } : detailResult);
+  } catch (err) {
+    res.status(500).json({ error: 'Failed to scan git repo detail', detail: String(err) });
+  }
+});

