new file mode 100644
index 0000000..4c9cba4
--- /dev/null
+++ b/src/components/git/gitContext.ts
@@ -0,0 +1,140 @@
+import type { GitFileEntry, GitRepoDetail, GitRepoSummary } from '../../types/git';
+import { buildGitChipContext } from './gitActionText';
+
+/**
+ * Onglet Git du détail projet (LOT 6) — construit le snippet « Contexte git »
+ * AU GABARIT EXACT de la spec § 01, à partir du DÉTAIL déjà chargé (jamais un
+ * fetch depuis cette fonction — pure, testable sans réseau ni DOM).
+ *
+ * Mirroir volontaire de `buildContextSnippet()` (`server/cli/git.ts`, LOT 3) :
+ * même gabarit exposé à la CLI (parité Codex) et à l'UI — une seule vérité du
+ * format, deux runtimes. Toute évolution du gabarit doit être répercutée aux
+ * DEUX endroits (pas d'import cross server/src ici : le composant frontend ne
+ * doit dépendre que de `src/**`).
+ *
+ * Lignes conditionnelles (spec § 01, « pas de bruit quand vide ») :
+ *   - Dirty : omise si aucun fichier modifié.
+ *   - ALERTE identité : omise si `identityMismatch` est faux.
+ * La ligne finale (branches locales / worktrees / stash) reste TOUJOURS
+ * présente avec « aucun » plutôt qu'omise — comportement montré par
+ * l'exemple de la spec (« Worktrees : aucun · Stash : aucun »).
+ *
+ * Les « Comptes déclarés » / « Notes env » (registre providers, LOT 8) sont
+ * des lignes conditionnelles supplémentaires — omises si `detail.providerAccounts`
+ * est absent (repo qui n'a pas encore déclaré ses comptes). Mirroir volontaire
+ * de `buildContextSnippet()` (`server/cli/git.ts`) : toute évolution de ces
+ * lignes doit être répercutée aux DEUX endroits.
+ */
+
+/** Libellés d'affichage des 4 providers connus, dans un ordre stable. */
+const PROVIDER_LABELS: readonly ['vercel' | 'cloudflare' | 'convex' | 'workos', string][] = [
+  ['vercel', 'Vercel'],
+  ['cloudflare', 'Cloudflare'],
+  ['convex', 'Convex'],
+  ['workos', 'WorkOS'],
+];
+
+/** Code d'état porcelain v2 (colonne X/Y) pour un fichier — texte pur. */
+export function fileStateCode(f: GitFileEntry): string {
+  if (f.kind === 'untracked') return '??';
+  if (f.kind === 'submodule') return 'SUB';
+  if (f.kind === 'unmerged') return 'UU';
+  return `${f.indexStatus ?? '.'}${f.worktreeStatus ?? '.'}`;
+}
+
+export function buildGitContext(detail: GitRepoDetail): string {
+  const lines: string[] = [];
+  lines.push(`Contexte git — ${detail.name} (${detail.path})`);
+
+  let branchLine: string;
+  if (detail.initial) {
+    branchLine = 'Branche : (initial) — aucun commit';
+  } else if (!detail.currentBranch) {
+    const oid = detail.detachedOid ? detail.detachedOid.slice(0, 7) : '?';
+    branchLine = `Branche : HEAD détaché (${oid})`;
+  } else {
+    const b = detail.branches.find((x) => x.name === detail.currentBranch);
+    let sync: string;
+    if (!b || !b.upstream) {
+      sync = 'aucune amont configurée (jamais poussée nulle part)';
+    } else if (b.track.gone) {
+      sync = `amont "${b.upstream}" supprimée [gone]`;
+    } else if (b.track.ahead > 0) {
+      sync = `${b.track.ahead} commit(s) en avance sur ${b.upstream} (jamais poussés)`;
+    } else if (b.track.behind > 0) {
+      sync = `à jour, ${b.track.behind} commit(s) en retard sur ${b.upstream}`;
+    } else {
+      sync = `à jour avec ${b.upstream}`;
+    }
+    branchLine = `Branche : ${detail.currentBranch} · ${sync}`;
+  }
+  lines.push(branchLine);
+
+  const dirtyTotal =
+    detail.dirty.staged + detail.dirty.unstaged + detail.dirty.untracked + detail.dirty.submodules;
+  if (dirtyTotal > 0) {
+    const names = detail.files.map((f) => `${f.path} (${fileStateCode(f)})`).join(', ');
+    lines.push(`Dirty : ${dirtyTotal} fichier(s) modifié(s) — ${names}`);
+  }
+
+  if (detail.identityMismatch) {
+    const detailText = detail.identity.mismatch.map((m) => m.detail).join(' ; ');
+    lines.push(`ALERTE identité : ${detailText}`);
+  }
+
+  const declaredProviders = detail.providerAccounts?.providers;
+  if (declaredProviders) {
+    const parts = PROVIDER_LABELS.filter(([key]) => declaredProviders[key]).map(
+      ([key, label]) => `${label}=${declaredProviders[key]}`,
+    );
+    if (parts.length > 0) {
+      lines.push(`Comptes déclarés : ${parts.join(' ')}`);
+    }
+  }
+  if (detail.providerAccounts?.envNotes) {
+    lines.push(`Notes env : ${detail.providerAccounts.envNotes}`);
+  }
+
+  const branchNames = detail.branches.map((b) => b.name).join(', ') || 'aucune';
+  const extraWorktrees = detail.worktrees.filter((w) => !w.isMain);
+  const worktreeSummary =
+    extraWorktrees.length === 0
+      ? 'aucun'
+      : `${extraWorktrees.length} (${extraWorktrees.map((w) => w.branch ?? '(détaché)').join(', ')})`;
+  const stashSummary =
+    detail.stashes.length === 0
+      ? 'aucun'
+      : `${detail.stashes.length} (${detail.stashes.map((s) => s.ref).join(', ')})`;
+  lines.push(`Branches locales : ${branchNames} · Worktrees : ${worktreeSummary} · Stash : ${stashSummary}`);
+
+  return lines.join('\n');
+}
+
+/**
+ * Contexte GROUPÉ multi-dépôts (spec § 01 : « l'audit du matin est multi-
+ * dépôts ») — un paragraphe `buildGitContext` par dépôt SÉLECTIONNÉ, séparés
+ * par une ligne vide, dans l'ordre de `slugs`.
+ *
+ * Le contexte groupé complet exige le DÉTAIL par dépôt (fichiers/branches/
+ * stashes/worktrees) ; pour un slug dont le détail n'a pas encore été
+ * pré-chargé (ou dont le pré-chargement a échoué), on replie sur le contexte
+ * RÉSUMÉ (`buildGitChipContext`, déjà utilisé par les actions rapides) plutôt
+ * que de bloquer la copie — voir la note d'implémentation dans
+ * `DashboardPage.tsx` (pré-chargement au moment de la coche, jamais d'await
+ * dans le handler du clic « Copier »).
+ */
+export function buildGroupedGitContext(
+  slugs: string[],
+  detailsBySlug: Record<string, GitRepoDetail>,
+  summariesBySlug: Record<string, GitRepoSummary>,
+): string {
+  return slugs
+    .map((slug) => {
+      const detail = detailsBySlug[slug];
+      if (detail) return buildGitContext(detail);
+      const summary = summariesBySlug[slug];
+      if (summary) return buildGitChipContext(summary);
+      return `Contexte git — ${slug} (détail indisponible — rescan nécessaire)`;
+    })
+    .join('\n\n');
+}

diff --git a/src/components/git/GitQuickActions.tsx b/src/components/git/GitQuickActions.tsx
new file mode 100644
index 0000000..dca8c67
--- /dev/null
+++ b/src/components/git/GitQuickActions.tsx
@@ -0,0 +1,182 @@
+import { useCallback, useEffect, useRef, useState } from 'react';
+import { Bell, Check, ClipboardPlus } from 'lucide-react';
+import type { GitRepoSummary } from '../../types/git';
+import type { Conversation, ReminderItem } from '../../types/conversation';
+import { ApiError, createChip, getConversation, saveConversation } from '../../lib/api';
+import { buildGitChipContext, computeGitReminderDueAt, describeGitAction, type GitReminderDueChoice } from './gitActionText';
+
+const REMINDERS_SLUG = '_reminders';
+const REMINDERS_ID = 'rappels';
+
+/** Même schéma d'id que `RemindersSection` — pas exporté de là, donc reproduit
+ *  ici à l'identique plutôt qu'importé (§ chantier : « réutilise newItemId()
+ *  comme RemindersSection »). */
+function newItemId(): string {
+  return `reminder-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
+}
+
+const DUE_CHOICES: { choice: GitReminderDueChoice; label: string }[] = [
+  { choice: 'tonight', label: 'Ce soir' },
+  { choice: 'tomorrow', label: 'Demain' },
+  { choice: 'none', label: 'Sans échéance' },
+];
+
+/**
+ * Gestes rapides « créer un rappel » / « créer un chip » depuis une ligne git
+ * (spec § 04, V1) — les deux mécanismes existent déjà au hub (conversation
+ * évergreen `_reminders/rappels`, comme `RemindersSection` ; store chips), on
+ * se contente de les brancher avec le contexte git déjà chargé (`repo`), sans
+ * fetch supplémentaire.
+ */
+export function GitQuickActions({ repo }: { repo: GitRepoSummary }) {
+  const [popoverOpen, setPopoverOpen] = useState(false);
+  const [reminderBusy, setReminderBusy] = useState(false);
+  const [reminderDone, setReminderDone] = useState(false);
+  const [chipBusy, setChipBusy] = useState(false);
+  const [chipDone, setChipDone] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const rootRef = useRef<HTMLDivElement>(null);
+
+  useEffect(() => {
+    if (!popoverOpen) return;
+    const onDown = (e: MouseEvent) => {
+      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setPopoverOpen(false);
+    };
+    window.addEventListener('mousedown', onDown);
+    return () => window.removeEventListener('mousedown', onDown);
+  }, [popoverOpen]);
+
+  const createReminder = useCallback(
+    async (choice: GitReminderDueChoice) => {
+      setPopoverOpen(false);
+      setReminderBusy(true);
+      setError(null);
+      const now = new Date().toISOString();
+      try {
+        let conversation: Conversation | null = null;
+        try {
+          conversation = await getConversation(REMINDERS_SLUG, REMINDERS_ID);
+        } catch (err) {
+          if (!(err instanceof ApiError && err.status === 404)) throw err;
+        }
+        const base: Conversation =
+          conversation ?? {
+            schemaVersion: 1,
+            id: REMINDERS_ID,
+            project: { slug: REMINDERS_SLUG, name: 'Rappels' },
+            title: 'Rappels',
+            summary:
+              "Rappels accumulés au fil du temps, ajoutés depuis n'importe quel projet via `bun run remind add`.",
+            status: 'pending',
+            items: [],
+            createdAt: now,
+            updatedAt: now,
+            createdBy: 'user',
+          };
+        const text = describeGitAction(repo);
+        const item: ReminderItem = {
+          id: newItemId(),
+          kind: 'reminder',
+          title: 'Rappel',
+          prompt: text,
+          body: text,
+          status: 'pending',
+          priority: repo.level === 'blocked' || repo.level === 'at-risk' ? 'high' : 'normal',
+          dueAt: computeGitReminderDueAt(choice),
+        };
+        const next: Conversation = { ...base, items: [...base.items, item] };
+        await saveConversation(next);
+        setReminderDone(true);
+        window.setTimeout(() => setReminderDone(false), 2500);
+      } catch (err) {
+        setError(err instanceof ApiError ? err.message : "Impossible de créer ce rappel.");
+      } finally {
+        setReminderBusy(false);
+      }
+    },
+    [repo],
+  );
+
+  const createGitChip = useCallback(async () => {
+    setChipBusy(true);
+    setError(null);
+    try {
+      await createChip({
+        title: describeGitAction(repo),
+        prompt: buildGitChipContext(repo),
+        tldr: `Contexte git observé automatiquement — ${repo.name}.`,
+        cwd: repo.path,
+      });
+      setChipDone(true);
+      window.setTimeout(() => setChipDone(false), 2500);
+    } catch (err) {
+      setError(err instanceof ApiError ? err.message : 'Impossible de créer ce chip.');
+    } finally {
+      setChipBusy(false);
+    }
+  }, [repo]);
+
+  return (
+    <div ref={rootRef} className="relative flex shrink-0 items-center gap-1.5">
+      <div className="relative">
+        <button
+          type="button"
+          onClick={() => setPopoverOpen((o) => !o)}
+          disabled={reminderBusy}
+          aria-haspopup="true"
+          aria-expanded={popoverOpen}
+          title={`Créer un rappel pour ${repo.name}`}
+          className="flex h-8 w-8 items-center justify-center rounded-md border border-line text-ink-faint transition-colors hover:border-copper/50 hover:text-copper disabled:cursor-not-allowed disabled:opacity-50"
+        >
+          {reminderDone ? (
+            <Check className="h-3.5 w-3.5 text-status-done" aria-hidden />
+          ) : (
+            <Bell className="h-3.5 w-3.5" aria-hidden />
+          )}
+        </button>
+        {popoverOpen && (
+          <div
+            role="menu"
+            aria-label="Échéance du rappel"
