+import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
+import type { GitRepoSummary } from '../types/git';
+import { ApiError, getGitDetail, getGitStatus } from '../lib/api';
+import { useServerEvents } from './useServerEvents';
+
+export type GitStatusPhase = 'loading' | 'ready' | 'error';
+
+export interface UseGitStatusResult {
+  /** Résumés bruts, dans l'ordre renvoyé par le serveur (tri = à la charge du consommateur). */
+  repos: GitRepoSummary[];
+  /** Fusion par slug — pratique pour croiser avec `ProjectSummary` (LOT 5). */
+  bySlug: Record<string, GitRepoSummary>;
+  /**
+   * `'loading'` tant que le PREMIER fetch n'a pas résolu : aucun slug n'a de
+   * donnée fiable, `bySlug` est vide. Un consommateur DOIT gater sur cette
+   * valeur (pastille « en cours ») plutôt que de traiter un slug absent de
+   * `bySlug` comme "propre" — spec § 03 : jamais de fausse tranquillité par
+   * absence de donnée.
+   */
+  status: GitStatusPhase;
+  error: string | null;
+  /** `true` quand le dernier refresh (global ou ciblé) a été throttlé côté
+   *  serveur (cooldown ~2s) — le dernier état connu a été conservé tel quel. */
+  throttled: boolean;
+  /** Relance un scan complet (`?refresh=1`, single-flight côté serveur). */
+  refresh: () => Promise<void>;
+  /** `true` pendant un `refresh()` global en vol. */
+  refreshing: boolean;
+  /** Relance un scan CIBLÉ d'un seul dépôt (`GET /api/git/:slug?refresh=1`) et
+   *  fusionne le résultat dans `repos`/`bySlug` sans attendre un rescan complet. */
+  refreshOne: (slug: string) => Promise<void>;
+  /** Slugs actuellement en cours de refresh ciblé (`refreshOne`). */
+  refreshingSlugs: Set<string>;
+}
+
+/**
+ * Fusionne `detail` dans `repos` par slug — remplace en place si un dépôt de
+ * ce slug est déjà présent, APPEND sinon (dépôt tout juste apparu sous
+ * PROJECTS_ROOT, jamais vu par ce hook depuis son premier `load()`).
+ *
+ * FIX P2 (revue adversariale) : un `git-changed {slug}` reçu pour un dépôt
+ * ABSENT de `repos` faisait auparavant un no-op silencieux
+ * (`prev.map(r => r.slug === slug ? detail : r)` ne matche rien) — le
+ * nouveau dépôt n'apparaissait alors jamais sans un refetch complet, alors
+ * que le serveur (`rescanRepo()`) gère déjà l'ajout-si-absent côté cache.
+ * Extrait en fonction PURE (même idiome que `mergeScanResults` côté serveur
+ * et `shouldAutoOpenOnPaste`) pour rester testable unitairement — ce hook
+ * n'a pas d'infra de rendu React (`renderHook`) dans ce repo.
+ */
+export function upsertRepoBySlug(
+  repos: GitRepoSummary[],
+  slug: string,
+  detail: GitRepoSummary,
+): GitRepoSummary[] {
+  const idx = repos.findIndex((r) => r.slug === slug);
+  return idx === -1 ? [...repos, detail] : repos.map((r, i) => (i === idx ? detail : r));
+}
+
+/**
+ * Observatoire Git — état côté client (LOT 4). Un seul fetch global
+ * (`GET /api/git/status`) alimente `repos`/`bySlug` ; `refreshOne` permet en
+ * plus de rafraîchir UN dépôt sans attendre un rescan des ~21 autres.
+ *
+ * Dépendances d'effet = PRIMITIVES uniquement (règle react-effects) : les
+ * callbacks internes sont mémoïsés avec des tableaux de dépendances vides ou
+ * primitifs, jamais un objet recréé à chaque rendu.
+ */
+export function useGitStatus(): UseGitStatusResult {
+  const [repos, setRepos] = useState<GitRepoSummary[]>([]);
+  const [status, setStatus] = useState<GitStatusPhase>('loading');
+  const [error, setError] = useState<string | null>(null);
+  const [throttled, setThrottled] = useState(false);
+  const [refreshing, setRefreshing] = useState(false);
+  const [refreshingSlugs, setRefreshingSlugs] = useState<Set<string>>(new Set());
+
+  // RACE 2 (revue adversariale) : un SEUL compteur monotone, PARTAGÉ entre
+  // `load()` (fetch global) et `fetchSlugDetail()` (fetch ciblé) — chaque fetch
+  // tire son numéro `mySeq` AU DÉBUT, avant de partir en requête. `appliedSeqRef`
+  // retient, PAR SLUG, le plus grand numéro déjà APPLIQUÉ à l'affichage. À la
+  // résolution d'un fetch, sa donnée pour un slug n'est appliquée QUE si
+  // `mySeq >= appliedSeq(slug)` — ce qui ordonne correctement les deux sources
+  // de vérité l'une par rapport à l'autre : un `load()` global lent ne peut
+  // plus régresser un slug déjà rafraîchi par un `fetchSlugDetail()` plus
+  // récent (parti après lui), et inversement. Refs (pas de re-render) : ce
+  // n'est pas un état affiché, juste un ordonnancement.
+  const seqCounterRef = useRef(0);
+  const appliedSeqRef = useRef<Map<string, number>>(new Map());
+
+  const load = useCallback(async (forceRefresh: boolean) => {
+    if (forceRefresh) setRefreshing(true);
+    setError(null);
+    const mySeq = ++seqCounterRef.current;
+    try {
+      const data = await getGitStatus(forceRefresh ? { refresh: true } : undefined);
+      setRepos((prev) => {
+        const prevBySlug = new Map(prev.map((r) => [r.slug, r] as const));
+        return data.repos.map((incoming) => {
+          const applied = appliedSeqRef.current.get(incoming.slug) ?? 0;
+          if (mySeq >= applied) {
+            appliedSeqRef.current.set(incoming.slug, mySeq);
+            return incoming;
+          }
+          // Un `fetchSlugDetail()` plus récent (parti après ce `load()`) a
+          // déjà appliqué une donnée plus fraîche pour ce slug — on la garde
+          // plutôt que de la faire régresser avec la réponse (plus ancienne)
+          // de ce `load()`.
+          return prevBySlug.get(incoming.slug) ?? incoming;
+        });
+      });
+      setThrottled(data.throttled === true);
+      setStatus('ready');
+    } catch (err) {
+      setError(err instanceof ApiError ? err.message : "Erreur inattendue lors du scan de l'observatoire Git.");
+      setStatus('error');
+    } finally {
+      if (forceRefresh) setRefreshing(false);
+    }
+  }, []);
+
+  useEffect(() => {
+    void load(false);
+  }, [load]);
+
+  /**
+   * Refetch ciblé d'UN dépôt, gardé PAR LE MÊME compteur monotone que `load()`
+   * (voir `seqCounterRef`/`appliedSeqRef` ci-dessus) — appelé aussi bien par
+   * `refreshOne` (bouton manuel, `markRefreshing = true`) que par le handler
+   * `git-changed` (LOT 7, `markRefreshing = false` : pas de pastille "en
+   * cours" pour un refresh déclenché en arrière-plan par un commit d'une
+   * session Claude).
+   */
+  const fetchSlugDetail = useCallback(async (slug: string, markRefreshing: boolean) => {
+    const mySeq = ++seqCounterRef.current;
+
+    if (markRefreshing) {
+      setRefreshingSlugs((prev) => {
+        const next = new Set(prev);
+        next.add(slug);
+        return next;
+      });
+    }
+    try {
+      const detail = await getGitDetail(slug, markRefreshing ? { refresh: true } : undefined);
+      // Une requête plus récente pour ce MÊME slug (ou un `load()` global parti
+      // après celle-ci) a déjà appliqué une donnée plus fraîche — cette
+      // réponse est PÉRIMÉE, on ne l'applique pas (jamais de régression
+      // d'affichage, spec § 03/LOT 7).
+      const applied = appliedSeqRef.current.get(slug) ?? 0;
+      if (mySeq < applied) return;
+      appliedSeqRef.current.set(slug, mySeq);
+      setThrottled(detail.throttled === true);
+      setRepos((prev) => upsertRepoBySlug(prev, slug, detail));
+    } catch {
+      // Un refresh ciblé qui échoue ne doit pas invalider les autres lignes
+      // déjà affichées — le prochain scan (cache TTL, refresh global, ou le
+      // prochain `git-changed`) rattrapera ce dépôt.
+    } finally {
+      if (markRefreshing) {
+        setRefreshingSlugs((prev) => {
+          const next = new Set(prev);
+          next.delete(slug);
+          return next;
+        });
+      }
+    }
+  }, []);
+
+  // Réveil temps réel (LOT 7) :
+  //  - `git-changed {slug}` (watchers .git serveur, ordre rescan-avant-publish
+  //    garanti côté serveur) -> refetch CIBLÉ de ce seul slug, gardé par
+  //    numéro de scan croissant.
+  //  - `projects-changed` (nouveau projet créé, ex. via l'UI) peut signifier
+  //    qu'un nouveau dépôt vient d'apparaître sous PROJECTS_ROOT -> refetch
+  //    global NON forcé (cache TTL 30s côté serveur) suffit à le faire remonter
+  //    sans transformer chaque clic ailleurs dans l'app en scan git.
+  const connected = useServerEvents(
+    useCallback(
+      (event) => {
+        if (event.type === 'git-changed' && event.slug) {
+          void fetchSlugDetail(event.slug, false);
+          return;
+        }
+        if (event.type === 'projects-changed') void load(false);
+      },
+      [load, fetchSlugDetail],
+    ),
+  );
+
+  // Android/iOS suspendent la PWA (et son SSE) en arrière-plan (spec § 01) :
+  // au retour au premier plan, refetch COMPLET inconditionnel — l'état affiché
+  // peut avoir plusieurs minutes de retard, un refetch ciblé par slug ne
+  // suffirait pas à rattraper tout ce qui a pu changer pendant l'absence.
+  useEffect(() => {
+    const onVisibilityChange = () => {
+      if (document.visibilityState === 'visible') void load(false);
+    };
+    document.addEventListener('visibilitychange', onVisibilityChange);
+    return () => document.removeEventListener('visibilitychange', onVisibilityChange);
+  }, [load]);
+
+  // Reconnexion SSE (`onopen` après un drop — pas la connexion initiale, déjà
+  // couverte par le `load(false)` du mount) : refetch COMPLET inconditionnel,
+  // des `git-changed` ont pu être manqués pendant la coupure (spec § 01).
+  const prevConnectedRef = useRef<boolean | null>(null);
+  useEffect(() => {
+    const wasConnected = prevConnectedRef.current;
+    prevConnectedRef.current = connected;
+    if (wasConnected === false && connected === true) {
+      void load(false);
+    }
+  }, [connected, load]);
+
+  const refresh = useCallback(() => load(true), [load]);
+
+  const refreshOne = useCallback((slug: string) => fetchSlugDetail(slug, true), [fetchSlugDetail]);
+
+  const bySlug = useMemo(() => {
+    const map: Record<string, GitRepoSummary> = {};
+    for (const r of repos) map[r.slug] = r;
+    return map;
+  }, [repos]);
+
+  return { repos, bySlug, status, error, throttled, refresh, refreshing, refreshOne, refreshingSlugs };
+}

