diff --git a/src/components/git/GitHeaderStatus.tsx b/src/components/git/GitHeaderStatus.tsx
new file mode 100644
index 0000000..14274f3
--- /dev/null
+++ b/src/components/git/GitHeaderStatus.tsx
@@ -0,0 +1,86 @@
+import { useEffect, useState } from 'react';
+import type { GitRepoSummary } from '../../types/git';
+import { ApiError, getGitDetail } from '../../lib/api';
+import { GitLevelBadge } from './GitLevelBadge';
+import { formatGitBranch, formatGitIdentity } from './gitFormat';
+
+type HeaderStatusPhase = 'loading' | 'ready' | 'error';
+
+/**
+ * Rappel COMPACT de l'état git au-dessus des onglets du détail projet
+ * (LOT 6, spec § 04 : « réciproquement l'état git en tête du détail
+ * projet »).
+ *
+ * FIX P2 SCALABILITÉ (revue adversariale) : ce composant s'abonnait
+ * auparavant à `useGitStatus()` — un scan de TOUTE la flotte
+ * (`GET /api/git/status`, ~7 `execFile` git PAR DÉPÔT) — juste pour un
+ * badge d'en-tête d'UN SEUL dépôt. Fetch DÉDIÉ et LÉGER désormais :
+ * `GET /api/git/:slug` (`getGitDetail`, désormais caché côté serveur — voir
+ * `scanGitDetail` dans `gitScanner.ts`) sur CE seul dépôt, plus de scan
+ * flotte pour un badge. Le détail riche (fichiers/branches/stashes/
+ * worktrees) reste réservé à l'onglet Git (`GitDetailPanel`), chargé
+ * seulement quand l'utilisateur y va.
+ *
+ * `phase === 'loading'` => squelette ; `phase === 'error'` OU dépôt introuvable
+ * (pas un dépôt git, ou 404) => rien n'est affiché, JAMAIS un badge "propre"
+ * par défaut (règle observatoire, spec § 03) — même contrat que l'ancienne
+ * version (`repo === undefined` => `null`), juste sans dépendre du scan de
+ * flotte pour l'obtenir.
+ */
+export function GitHeaderStatus({ slug, onOpenGitTab }: { slug: string; onOpenGitTab: () => void }) {
+  const [repo, setRepo] = useState<GitRepoSummary | null>(null);
+  const [phase, setPhase] = useState<HeaderStatusPhase>('loading');
+
+  useEffect(() => {
+    let cancelled = false;
+    setPhase('loading');
+    setRepo(null);
+
+    getGitDetail(slug)
+      .then((detail) => {
+        if (cancelled) return;
+        setRepo(detail);
+        setPhase('ready');
+      })
+      .catch((err) => {
+        if (cancelled) return;
+        // Dépôt introuvable (projet pas encore/plus un dépôt git) ou échec
+        // de scan : le badge disparaît silencieusement (même comportement
+        // que l'ancienne version pour un slug absent de `bySlug`) — l'onglet
+        // Git complet reste la source d'erreur détaillée si besoin.
+        void (err instanceof ApiError ? err.message : String(err));
+        setRepo(null);
+        setPhase('error');
+      });
+
+    return () => {
+      cancelled = true;
+    };
+  }, [slug]);
+
+  if (phase === 'loading') {
+    return <div className="mt-3 h-6 w-48 animate-pulse rounded-md bg-paper-deep" aria-hidden />;
+  }
+  if (phase === 'error' || !repo) return null;
+
+  return (
+    <button
+      type="button"
+      onClick={onOpenGitTab}
+      title="Voir l'onglet Git de ce projet"
+      className="mt-3 flex flex-wrap items-center gap-2 rounded-md -ml-1 px-1 py-0.5 text-left transition-colors hover:bg-paper-deep/50"
+    >
+      <GitLevelBadge level={repo.level} />
+      <span className="font-mono text-xs text-ink-soft">{formatGitBranch(repo)}</span>
+      <span className="font-mono text-xs text-ink-faint">·</span>
+      <span className="font-mono text-xs text-ink-soft" title={repo.identity.remoteUrl ?? undefined}>
+        {formatGitIdentity(repo)}
+      </span>
+      {repo.identityMismatch && (
+        <span className="rounded-md border border-danger/35 bg-danger-bg px-1.5 py-0.5 font-mono text-[0.625rem] font-medium tracking-wide text-danger">
+          identité incohérente
+        </span>
+      )}
+    </button>
+  );
+}

