@@ -0,0 +1,379 @@
+import { useCallback, useEffect, useState } from 'react';
+import { Check, ClipboardPlus, Copy, RefreshCw } from 'lucide-react';
+import type { GitFileEntry, GitRepoDetail } from '../../types/git';
+import { ApiError, createChip, getGitDetail } from '../../lib/api';
+import { Button } from '../ui/Button';
+import { GitLevelBadge } from './GitLevelBadge';
+import { formatDeclaredProviderAccounts, formatGitIdentity } from './gitFormat';
+import { buildGitContext, fileStateCode } from './gitContext';
+import {
+  buildDeclareAccountsChipPrompt,
+  buildDeclareAccountsChipTitle,
+  buildDeclareAccountsChipTldr,
+} from './providerAccountsPrompt';
+
+const FILE_KIND_LABEL: Record<GitFileEntry['kind'], string> = {
+  unmerged: 'En conflit',
+  staged: 'Staged (indexés)',
+  unstaged: 'Modifiés (non indexés)',
+  untracked: 'Non suivis',
+  submodule: 'Sous-modules',
+};
+
+const FILE_KIND_ORDER: GitFileEntry['kind'][] = ['unmerged', 'staged', 'unstaged', 'untracked', 'submodule'];
+
+function formatRelative(iso: string | null): string | null {
+  if (!iso) return null;
+  const date = new Date(iso);
+  if (Number.isNaN(date.getTime())) return null;
+  const diffMs = Date.now() - date.getTime();
+  const diffMin = Math.round(diffMs / 60_000);
+  if (diffMin < 1) return "à l'instant";
+  if (diffMin < 60) return `il y a ${diffMin} min`;
+  const diffH = Math.round(diffMin / 60);
+  if (diffH < 24) return `il y a ${diffH} h`;
+  const diffD = Math.round(diffH / 24);
+  return `il y a ${diffD} j`;
+}
+
+function SectionCard({ title, count, children }: { title: string; count?: number; children: React.ReactNode }) {
+  return (
+    <section className="rounded-xl border border-line bg-paper-card p-4 sm:p-5">
+      <h3 className="font-display text-lg font-semibold text-ink">
+        {title}
+        {typeof count === 'number' && <span className="ml-2 font-mono text-xs text-ink-faint">({count})</span>}
+      </h3>
+      <div className="mt-3">{children}</div>
+    </section>
+  );
+}
+
+function EmptyRow({ children }: { children: React.ReactNode }) {
+  return <p className="font-mono text-xs text-ink-faint">{children}</p>;
+}
+
+/**
+ * Onglet « Git » du détail projet (LOT 6, ?tab=git) — vue profonde d'UN
+ * dépôt : fichiers par état, branches locales, stashes, worktrees, et le
+ * bouton « Copier le contexte pour Claude ». Fetch dédié (`getGitDetail`) au
+ * montage — état `loading | ready | error` explicite, JAMAIS un faux vide
+ * (règle observatoire, spec § 03).
+ */
+export function GitDetailPanel({ slug }: { slug: string }) {
+  const [detail, setDetail] = useState<GitRepoDetail | null>(null);
+  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading');
+  const [error, setError] = useState<string | null>(null);
+  const [refreshing, setRefreshing] = useState(false);
+  const [copied, setCopied] = useState(false);
+  // Distinct de `error` (échec de CHARGEMENT, qui remplace tout le panneau) —
+  // un échec de COPIE survient alors que `detail` est déjà affiché avec
+  // succès ; il doit s'afficher en ligne, pas remplacer le panneau entier.
+  const [copyError, setCopyError] = useState<string | null>(null);
+  // LOT 8 — action rapide « déclarer les comptes » : crée un CHIP prérempli
+  // (cwd = repo CIBLE), le hub n'écrit JAMAIS .claude/.workstation-accounts.json
+  // lui-même (doctrine Galley, Q6).
+  const [declareBusy, setDeclareBusy] = useState(false);
+  const [declareDone, setDeclareDone] = useState(false);
+  const [declareError, setDeclareError] = useState<string | null>(null);
+
+  const load = useCallback(
+    async (forceRefresh: boolean) => {
+      if (forceRefresh) setRefreshing(true);
+      else setStatus('loading');
+      setError(null);
+      try {
+        const data = await getGitDetail(slug, forceRefresh ? { refresh: true } : undefined);
+        setDetail(data);
+        setStatus('ready');
+      } catch (err) {
+        setError(err instanceof ApiError ? err.message : 'Erreur inattendue lors du scan de ce dépôt.');
+        setStatus('error');
+      } finally {
+        if (forceRefresh) setRefreshing(false);
+      }
+    },
+    [slug],
+  );
+
+  useEffect(() => {
+    void load(false);
+  }, [load]);
+
+  // Bouton « Copier le contexte pour Claude » — `writeText` DOIT être appelé
+  // SYNCHRONEMENT dans le handler du clic (contrainte WebKit / hygiène
+  // Android) : le texte est construit depuis `detail`, déjà chargé en state,
+  // AUCUN await ne précède l'appel.
+  function handleCopy() {
+    if (!detail) return;
+    setCopyError(null);
+    navigator.clipboard
+      .writeText(buildGitContext(detail))
+      .then(() => {
+        setCopied(true);
+        window.setTimeout(() => setCopied(false), 2500);
+      })
+      .catch(() => setCopyError('Impossible de copier le contexte — presse-papier indisponible.'));
+  }
+
+  const handleDeclareAccounts = useCallback(async () => {
+    if (!detail) return;
+    setDeclareBusy(true);
+    setDeclareError(null);
+    try {
+      await createChip({
+        title: buildDeclareAccountsChipTitle(detail.name),
+        prompt: buildDeclareAccountsChipPrompt(detail),
+        tldr: buildDeclareAccountsChipTldr(detail.name),
+        cwd: detail.path,
+      });
+      setDeclareDone(true);
+      window.setTimeout(() => setDeclareDone(false), 2500);
+    } catch (err) {
+      setDeclareError(err instanceof ApiError ? err.message : 'Impossible de créer ce chip.');
+    } finally {
+      setDeclareBusy(false);
+    }
+  }, [detail]);
+
+  if (status === 'loading') {
+    return (
+      <div className="space-y-3">
+        {Array.from({ length: 4 }).map((_, i) => (
+          <div key={i} className="h-20 animate-pulse rounded-xl border border-line bg-paper-card/70" />
+        ))}
+      </div>
+    );
+  }
+
+  if (status === 'error' || !detail) {
+    return (
+      <div className="rounded-lg border border-danger/30 bg-danger-bg px-4 py-3 text-sm text-danger">
+        <p>{error ?? 'Le scan de ce dépôt a échoué.'}</p>
+        <Button variant="secondary" size="sm" className="mt-3" onClick={() => void load(false)}>
+          Réessayer
+        </Button>
+      </div>
+    );
+  }
+
+  const filesByKind = FILE_KIND_ORDER.map((kind) => ({
+    kind,
+    files: detail.files.filter((f) => f.kind === kind),
+  })).filter((g) => g.files.length > 0);
+
+  const extraWorktrees = detail.worktrees.filter((w) => !w.isMain);
+  const declaredProviders = formatDeclaredProviderAccounts(detail);
+
+  return (
+    <div className="space-y-6">
+      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-line-soft pb-4">
+        <div className="flex flex-wrap items-center gap-2.5">
+          <GitLevelBadge level={detail.level} />
+          <span className="font-mono text-xs text-ink-soft" title={detail.identity.remoteUrl ?? undefined}>
+            {formatGitIdentity(detail)}
+          </span>
+        </div>
+        <div className="flex items-center gap-2">
+          <Button variant="secondary" size="sm" loading={refreshing} onClick={() => void load(true)}>
+            <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? 'animate-spin' : ''}`} aria-hidden />
+            Rafraîchir
+          </Button>
+          <Button variant="copper" size="sm" onClick={handleCopy}>
+            {copied ? <Check className="h-3.5 w-3.5" aria-hidden /> : <Copy className="h-3.5 w-3.5" aria-hidden />}
+            {copied ? 'Copié' : 'Copier le contexte pour Claude'}
+          </Button>
+        </div>
+      </div>
+
+      {copyError && (
+        <p className="rounded-lg border border-danger/30 bg-danger-bg px-4 py-2.5 text-sm text-danger">
+          {copyError}
+        </p>
+      )}
+
+      {/* LOT 8 — comptes providers déclarés in-repo (lecture seule, à côté de
+          l'identité git) — le hub MIRRORE, il n'écrit jamais ce fichier. */}
+      <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-line-soft bg-paper-raised px-4 py-3">
+        <div className="flex flex-wrap items-baseline gap-x-2 gap-y-1 font-mono text-xs">
+          <span className="uppercase tracking-wide text-ink-faint">Comptes providers</span>
+          {declaredProviders ? (
+            <span className="text-ink">{declaredProviders}</span>
+          ) : (
+            <span className="text-ink-faint">non déclaré</span>
+          )}
+          {detail.providerAccounts?.envNotes && (
+            <span className="text-ink-soft">· Notes env : {detail.providerAccounts.envNotes}</span>
+          )}
+          {detail.providerAccountsWarning && (
+            <span className="text-danger">· {detail.providerAccountsWarning}</span>
+          )}
+        </div>
+        <Button
+          variant="secondary"
+          size="sm"
+          loading={declareBusy}
+          onClick={() => void handleDeclareAccounts()}
+        >
+          {declareDone ? (
+            <Check className="h-3.5 w-3.5 text-status-done" aria-hidden />
+          ) : (
+            <ClipboardPlus className="h-3.5 w-3.5" aria-hidden />
+          )}
+          {declareDone ? 'Chip créé' : 'Déclarer les comptes'}
+        </Button>
+      </div>
+      {declareError && (
+        <p className="rounded-lg border border-danger/30 bg-danger-bg px-4 py-2.5 text-sm text-danger">
+          {declareError}
+        </p>
+      )}
+
+      {detail.opInProgress && (
+        <p className="rounded-lg border border-danger/30 bg-danger-bg px-4 py-3 text-sm text-danger">
+          Opération en cours : <strong>{detail.opInProgress}</strong> — ce dépôt est bloqué tant que non résolue ou
+          avortée.
+        </p>
+      )}
+
+      {detail.identityMismatch && (
+        <div className="space-y-1.5 rounded-lg border border-danger/30 bg-danger-bg px-4 py-3 text-sm text-danger">
+          {detail.identity.mismatch.map((m, i) => (
+            <p key={i}>{m.detail}</p>
+          ))}
+        </div>
+      )}
+
+      {/* Fichiers */}
+      <SectionCard
+        title="Fichiers"
+        count={detail.dirty.staged + detail.dirty.unstaged + detail.dirty.untracked + detail.dirty.submodules}
+      >
+        {filesByKind.length === 0 ? (
+          <EmptyRow>Aucun fichier modifié — working tree propre.</EmptyRow>
+        ) : (
+          <div className="space-y-3">
+            {filesByKind.map(({ kind, files }) => (
+              <div key={kind}>
+                <p className="font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
+                  {FILE_KIND_LABEL[kind]} ({files.length})
+                </p>
+                <ul className="mt-1.5 space-y-1">
+                  {files.map((f) => (
+                    <li
+                      key={f.path}
+                      className="flex items-center gap-2 font-mono text-xs text-ink-soft"
+                    >
+                      <span className="shrink-0 rounded border border-line bg-paper-deep px-1 py-0.5 text-[0.625rem] text-ink-faint">
+                        {fileStateCode(f)}
+                      </span>
+                      {/* Nom de fichier en TEXTE PUR — jamais dangerouslySetInnerHTML. */}
+                      <span className="truncate">{f.path}</span>
+                    </li>
+                  ))}
+                </ul>
+              </div>
+            ))}
+          </div>
+        )}
+      </SectionCard>
+
+      {/* Branches locales */}
+      <SectionCard title="Branches locales" count={detail.branches.length}>
+        {detail.branches.length === 0 ? (
+          <EmptyRow>Aucune branche locale.</EmptyRow>
+        ) : (
+          <ul className="space-y-2">
+            {detail.branches.map((b) => {
+              const relDate = formatRelative(b.lastCommitDate);
+              return (
+                <li
+                  key={b.name}
+                  className="flex flex-wrap items-center gap-x-2.5 gap-y-1 rounded-lg border border-line-soft bg-paper-raised px-3 py-2 font-mono text-xs"
+                >
+                  <span className="text-ink">{b.name}</span>
+                  {b.name === detail.currentBranch && (
+                    <span className="rounded-full border border-copper/30 bg-copper-tint px-1.5 py-0.5 text-[0.625rem] text-copper-deep">
+                      courante
+                    </span>
+                  )}
+                  {b.track.gone ? (
+                    <span className="text-danger">amont supprimé [gone]</span>
+                  ) : b.upstream ? (
+                    <span className="text-ink-faint">
+                      {b.upstream}
+                      {b.track.ahead > 0 && ` · ↑${b.track.ahead}`}
+                      {b.track.behind > 0 && ` · ↓${b.track.behind}`}
+                    </span>
+                  ) : (
+                    <span className="text-ink-faint">sans upstream</span>
+                  )}
+                  {b.mergedIntoDefault && (
+                    <span className="rounded-full border border-status-done/30 bg-status-done-bg px-1.5 py-0.5 text-[0.625rem] text-status-done">
