/* -------------------------------------------------------------------------- */
/*  Shared connection — ONE EventSource for the whole app                     */
/*                                                                            */
/*  The browser caps HTTP/1.1 connections at ~6 per origin. With one          */
/*  EventSource per consumer (19 call sites, 3-4 mounted per page) the pool   */
/*  starves and ordinary fetches queue until they abort. All subscribers      */
/*  therefore share a single module-level connection, opened on the first     */
/*  subscribe and closed shortly after the last unsubscribe (the delay        */
/*  absorbs StrictMode's mount→unmount→mount churn in dev).                   */
/* -------------------------------------------------------------------------- */

type EventHandler = (event: ServerEvent) => void;
type StateHandler = (connected: boolean) => void;

let source: EventSource | null = null;
let closeTimer: number | null = null;
let reopenTimer: number | null = null;
let live = false;
const eventHandlers = new Set<EventHandler>();
const stateHandlers = new Set<StateHandler>();

/** Backoff before recreating a fatally-CLOSED shared source (avoid a tight loop). */
const REOPEN_DELAY_MS = 1000;

function broadcastState(next: boolean): void {
  live = next;
  for (const notify of stateHandlers) notify(next);
}

/** Map raw server frames onto the ServerEvent shape (legacy aliases kept). */
function normalize(raw: Record<string, unknown> & { type?: string }): ServerEvent {
  if (raw.type === 'script-output' || raw.type === 'process-log') {
    return {
      type: 'process-log',
      slug: (raw.slug as string) ?? '',
      script: (raw.script as string) ?? (raw.name as string) ?? '',
      text: (raw.text as string) ?? (raw.logs as string) ?? '',
    };
  }
  if (raw.type === 'script-status' || raw.type === 'process-status') {
    return {
      type: 'process-status',
      slug: (raw.slug as string) ?? '',
      script: (raw.script as string) ?? (raw.name as string) ?? '',
      status: raw.status === 'running' ? 'running' : 'stopped',
      exitCode: raw.exitCode as number | undefined,
      cpu: raw.cpu as number | undefined,
      memory: raw.memory as number | undefined,
    };
  }
  if (raw.type === 'process-metrics') {
    return {
      type: 'process-metrics',
      slug: (raw.slug as string) ?? '',
      script: (raw.script as string) ?? (raw.name as string) ?? '',
      status: 'running',
      cpu: raw.cpu as number | undefined,
      memory: raw.memory as number | undefined,
    };
  }
  return raw as unknown as ServerEvent;
}

function openSharedSource(): void {
