+import type { GitLevel } from '../../types/git';
+
+/**
+ * Pastille de niveau (spec § 02) — teintes du thème atelier : `danger` pour
+ * bloqué/à risque, `warn` (status-progress) pour dirty, `copper` pour à
+ * noter, `ok` (status-done) pour propre, `ink-faint` pour inconnu (JAMAIS
+ * vert — un scan en échec ne doit jamais paraître propre).
+ */
+const LEVEL_META: Record<GitLevel, { label: string; className: string }> = {
+  blocked: { label: 'Bloqué', className: 'border-danger/35 bg-danger-bg text-danger' },
+  'at-risk': { label: 'À risque', className: 'border-danger/35 bg-danger-bg text-danger' },
+  dirty: {
+    label: 'Dirty',
+    className: 'border-status-progress/35 bg-status-progress-bg text-status-progress',
+  },
+  noteworthy: { label: 'À noter', className: 'border-copper/30 bg-copper-tint text-copper-deep' },
+  clean: { label: 'Propre', className: 'border-status-done/30 bg-status-done-bg text-status-done' },
+  unknown: { label: 'Inconnu', className: 'border-line bg-paper-deep text-ink-faint' },
+};
+
+export function gitLevelLabel(level: GitLevel): string {
+  return LEVEL_META[level].label;
+}
+
+export function GitLevelBadge({ level, className = '' }: { level: GitLevel; className?: string }) {
+  const meta = LEVEL_META[level];
+  return (
+    <span
+      className={`inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 font-mono text-[0.6875rem] font-medium tracking-wide whitespace-nowrap ${meta.className} ${className}`}
+    >
+      <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-current" aria-hidden />
+      {meta.label}
+    </span>
+  );
+}
