+/**
+ * Croisement hub (spec § 04, V1) : conversations et chips OUVERTS pour un
+ * slug donné — fusionné côté `DashboardPage` depuis les APIs existantes
+ * (`getConversations`, `getChips`), jamais un nouveau store. Alimente la
+ * pastille transversale « en attente de toi » (spec § 02).
+ */
+export interface GitCrossCounts {
+  openConversations: number;
+  openChips: number;
+}
+
+export function hasPendingHubWork(cross: GitCrossCounts | undefined): boolean {
+  return !!cross && (cross.openConversations > 0 || cross.openChips > 0);
+}
