+import type { GitLevel, GitRepoSummary } from '../../types/git';
+
+/**
+ * Tri « à risque d'abord » (spec § 02) — MIROIR du tri de `server/cli/git.ts`
+ * (`sortAtRiskFirst`/`sortRank`) : parité stricte entre la CLI et l'UI, un
+ * dépôt `identityMismatch` mais par ailleurs `clean` est remonté juste avant
+ * les vrais dépôts propres plutôt que noyé en bas de liste.
+ */
+const LEVEL_ORDER: Record<GitLevel, number> = {
+  blocked: 0,
+  'at-risk': 1,
+  dirty: 2,
+  noteworthy: 3,
+  clean: 4,
+  unknown: 5,
+};
+
+function sortRank(r: GitRepoSummary): number {
+  const base = LEVEL_ORDER[r.level];
+  if (r.identityMismatch && base > LEVEL_ORDER.noteworthy) {
+    return LEVEL_ORDER.noteworthy - 0.5;
+  }
+  return base;
+}
+
+export function sortGitReposAtRiskFirst(repos: GitRepoSummary[]): GitRepoSummary[] {
+  return [...repos].sort((a, b) => sortRank(a) - sortRank(b) || a.name.localeCompare(b.name, 'fr'));
+}

