+
+  return (
+    <div className="hidden overflow-x-auto rounded-lg border border-line bg-paper-card md:block">
+      <table className="w-full text-left text-sm">
+        <thead>
+          <tr className="border-b border-line bg-paper-deep/60">
+            <th className={`${HEAD_CLASS} w-10`}>
+              <input
+                type="checkbox"
+                checked={allSelected}
+                ref={(el) => {
+                  if (el) el.indeterminate = someSelected && !allSelected;
