+            </th>
+            <th className={HEAD_CLASS}>Projet</th>
+            <th className={HEAD_CLASS}>Branche</th>
+            <th className={HEAD_CLASS}>Fichiers</th>
+            <th className={HEAD_CLASS}>Synchro</th>
+            <th className={HEAD_CLASS}>Identité</th>
+            <th className={HEAD_CLASS}>Branches</th>
+            <th className={`${HEAD_CLASS} text-right`}>
+              <span className="sr-only">Rafraîchir</span>
+            </th>
+          </tr>
+        </thead>
+        <tbody>
+          {repos.map((repo) => {
+            const refreshing = refreshingSlugs.has(repo.slug);
+            const selected = selectedSlugs.has(repo.slug);
+            return (
+              <tr
+                key={repo.slug}
+                className={`border-b border-line-soft last:border-b-0 hover:bg-paper-deep/30 ${selected ? 'bg-copper-tint/20' : ''}`}
+              >
+                <td className="px-4 py-3 align-top">
+                  <input
+                    type="checkbox"
+                    checked={selected}
+                    onChange={() => onToggleSelect(repo.slug)}
