+                    <GitCrossBadges identityMismatch={repo.identityMismatch} cross={crossCounts[repo.slug]} />
+                  </div>
+                </td>
+                <td className="px-4 py-3 align-top font-mono text-xs text-ink-soft">{formatGitBranch(repo)}</td>
+                <td className="px-4 py-3 align-top font-mono text-xs text-ink-soft">{formatGitDirty(repo)}</td>
+                <td className="px-4 py-3 align-top font-mono text-xs text-ink-soft">{formatGitSync(repo)}</td>
+                <td className="px-4 py-3 align-top font-mono text-xs text-ink-soft" title={repo.identity.remoteUrl ?? undefined}>
+                  {formatGitIdentity(repo)}
+                </td>
+                <td className="px-4 py-3 align-top font-mono text-xs text-ink-soft">{repo.branchCount}</td>
+                <td className="px-4 py-3 align-top text-right">
+                  <button
+                    type="button"
+                    onClick={() => onRefreshOne(repo.slug)}
+                    disabled={refreshing}
+                    aria-label={`Rafraîchir ${repo.name}`}
+                    title="Rafraîchir ce dépôt"
+                    className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-line text-ink-soft transition-colors hover:border-copper/50 hover:text-copper disabled:cursor-not-allowed disabled:opacity-50"
+                  >
+                    <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? 'animate-spin' : ''}`} aria-hidden />
+                  </button>
+                </td>
+              </tr>
+            );
+          })}
+        </tbody>
+      </table>
+    </div>
+  );
+}

