+import type { GitRepoSummary } from '../../types/git';
+import { formatGitBranch, formatGitDirty, formatGitIdentity, formatGitSync } from './gitFormat';
+
+/**
+ * Gestes rapides « rappel » / « chip » depuis une ligne git (spec § 04, V1 —
+ * les deux mécanismes existent déjà au hub, on ne fait que les brancher avec
+ * le contexte git déjà chargé). Fonctions pures, testables sans DOM ni réseau
+ * — `GitQuickActions.tsx` ne fait que les appeler et gérer l'état async.
+ */
+
+/**
+ * Libellé d'action pour un dépôt — sert à la fois de corps de rappel et de
+ * titre de chip. Priorité STRICTE, la plus critique gagne (miroir de la
+ * hiérarchie d'alerte de `GitLevelBadge`/`gitSort`) :
+ *   1. commits jamais poussés (le signal le plus actionnable qui soit)
+ *   2. opération git interrompue (bloqué)
+ *   3. identité incohérente
+ *   4. dirty (fichiers modifiés)
+ *   5. à noter / inconnu / propre — libellé générique
+ *
+ * AUCUN compteur VOLATIL dans ce libellé (revue adversariale pré-PR, P2) : ce
+ * texte sert de TITRE de chip, et `createChip` calcule `dedupKey =
+ * slugify(title)` (`server/services/chipStore.ts`) — un titre du genre
+ * « Pousser frq (7 commits en avance) » change de dedupKey à chaque commit
+ * supplémentaire, donc à chaque re-scan un NOUVEAU chip est créé au lieu de
+ * fusionner dans l'existant (dédup cassée pour le signal le plus important :
+ * commits jamais poussés). Le compte EXACT reste affiché — mais uniquement
+ * dans le CORPS (`buildGitChipContext` -> ligne « Synchro : ↑ N non poussé(s) »
+ * via `formatGitSync`, remplacée à chaque fusion), jamais dans ce titre.
+ */
+export function describeGitAction(
+  repo: Pick<GitRepoSummary, 'name' | 'level' | 'aheadTotal' | 'dirty' | 'identityMismatch'>,
+): string {
+  if (repo.aheadTotal > 0) {
+    return `Pousser ${repo.name} (commits en avance)`;
+  }
+  if (repo.level === 'blocked') {
+    return `Débloquer ${repo.name} (opération git interrompue)`;
+  }
+  if (repo.identityMismatch) {
+    return `Vérifier l'identité de ${repo.name}`;
+  }
+  const dirtyTotal = repo.dirty.staged + repo.dirty.unstaged + repo.dirty.untracked + repo.dirty.submodules;
+  if (dirtyTotal > 0) {
+    return `Nettoyer ${repo.name} (dirty)`;
+  }
+  if (repo.level === 'noteworthy') {
+    return `Revoir ${repo.name} (à noter)`;
+  }
+  if (repo.level === 'unknown') {
+    return `Vérifier ${repo.name} (scan git en échec)`;
+  }
+  return `Vérifier ${repo.name}`;
+}
+
+/**
+ * Contexte git en TEXTE PUR pour un chip créé depuis l'observatoire — mêmes
+ * formatteurs que l'onglet Git (`gitFormat.ts`), jamais de contenu de fichier
+ * ni de diff (verrou spec § 03).
+ */
+export function buildGitChipContext(
+  repo: Pick<
+    GitRepoSummary,
+    | 'name'
+    | 'path'
+    | 'currentBranch'
+    | 'detachedOid'
+    | 'initial'
+    | 'dirty'
+    | 'aheadTotal'
+    | 'refsFreshness'
+    | 'identity'
+    | 'identityMismatch'
+  >,
+): string {
+  return [
+    `Contexte git — ${repo.name} (${repo.path})`,
+    `Branche : ${formatGitBranch(repo)}`,
+    `Synchro : ${formatGitSync(repo)}`,
+    `Dirty : ${formatGitDirty(repo)}`,
+    `Identité : ${formatGitIdentity(repo)}${repo.identityMismatch ? ' — INCOHÉRENTE' : ''}`,
+  ].join('\n');
+}
+
+export type GitReminderDueChoice = 'tonight' | 'tomorrow' | 'none';
+
+/**
+ * `dueAt` ISO pour les 3 choix du popover rappel — « ce soir » (~20h locale),
+ * « demain » (~9h locale), « sans échéance » (`undefined`). Prend `now` en
+ * paramètre pour rester testable sans mocker `Date` globalement.
+ *
+ * Pour « ce soir », si la cible 20h-aujourd'hui est déjà passée (choix fait
+ * après 20h), on replie sur `max(cible, now + 1h)` pour garantir un `dueAt`
+ * strictement dans le futur (jamais un rappel immédiatement en retard).
+ */
+export function computeGitReminderDueAt(choice: GitReminderDueChoice, now: Date = new Date()): string | undefined {
+  if (choice === 'none') return undefined;
+  if (choice === 'tonight') {
+    const target = new Date(now);
+    target.setHours(20, 0, 0, 0);
+    if (target.getTime() <= now.getTime()) {
+      return new Date(now.getTime() + 60 * 60 * 1000).toISOString();
+    }
+    return target.toISOString();
+  }
+  const d = new Date(now);
+  d.setDate(d.getDate() + 1);
+  d.setHours(9, 0, 0, 0);
+  return d.toISOString();
+}

