+import { ChevronRight } from 'lucide-react';
+import { Link } from 'react-router-dom';
+import type { GitRepoSummary } from '../../types/git';
+import type { GitStatusPhase } from '../../hooks/useGitStatus';
+import { GitLevelBadge } from './GitLevelBadge';
+import { formatGitBranch, formatGitSync } from './gitFormat';
+import { computeGitWatchPanelState } from './gitWatchPanelState';
+import { sortGitReposAtRiskFirst } from './gitSort';
+
+/** Combien de lignes affichées avant de renvoyer vers l'onglet Git complet
+ *  (spec § 02 : « un plafond silencieux mentirait »). */
+const CAP = 5;
+
+function isWatchworthy(repo: GitRepoSummary): boolean {
+  return repo.level === 'blocked' || repo.level === 'at-risk' || repo.identityMismatch;
+}
+
+/**
+ * Panneau « Git à surveiller » de la Vue d'ensemble (spec § 02, § 01 carte 2)
+ * — les dépôts `blocked` / `at-risk` / en incohérence d'identité, triés
+ * « à risque d'abord » (même tri que l'onglet Git), plafonnés avec un
+ * « + N autres » CLIQUABLE vers l'onglet Git complet : N est le compte EXACT
+ * de ce qui déborde du plafond, jamais approximatif.
+ */
+export function GitWatchPanel({
+  repos,
+  status,
+  error,
+  onSeeAll,
+}: {
+  repos: GitRepoSummary[];
+  status: GitStatusPhase;
+  error: string | null;
+  onSeeAll: () => void;
+}) {
+  const watch = sortGitReposAtRiskFirst(repos.filter(isWatchworthy));
+  const shown = watch.slice(0, CAP);
+  const rest = watch.length - shown.length;
+
+  // FIX P2 (revue adversariale) : `repos.length === 0` (rien n'a encore été
+  // scanné) et `watch.length === 0 && repos.length > 0` (vrai « tout
+  // propre ») sont deux états DISTINCTS — les confondre affirmerait
+  // faussement une tranquillité jamais vérifiée, interdit cardinal de
+  // l'observatoire (même distinction que l'onglet Git du dashboard,
+  // `DashboardPage.tsx`). Décision centralisée dans `computeGitWatchPanelState`
+  // (fonction pure, testée unitairement) pour ne pas la refaire à la main ici.
+  const panelState = computeGitWatchPanelState(status, repos.length, watch.length);
+
+  if (panelState === 'loading') {
+    return (
+      <div className="space-y-2">
+        {Array.from({ length: 3 }).map((_, index) => (
+          <div key={index} className="h-14 animate-pulse rounded-lg border border-line bg-paper-card/70" />
+        ))}
+      </div>
+    );
+  }
+
+  if (panelState === 'error') {
+    return (
+      <p className="rounded-lg border border-danger/30 bg-danger-bg px-4 py-3 text-sm text-danger">
+        {error ?? "Le scan de l'Observatoire Git a échoué."}
+      </p>
+    );
+  }
+
+  if (panelState === 'unscanned') {
+    return (
+      <p className="rounded-lg border border-dashed border-line bg-paper-card/60 px-4 py-8 text-center text-sm text-ink-faint">
+        Aucun dépôt git scanné pour l'instant.
+      </p>
+    );
+  }
+
+  if (panelState === 'clean') {
+    return (
+      <p className="rounded-lg border border-dashed border-line bg-paper-card/60 px-4 py-8 text-center text-sm text-ink-faint">
+        Rien à surveiller — tous les dépôts scannés sont propres et l’identité est cohérente partout.
+      </p>
+    );
+  }
+
+  return (
+    <div className="overflow-hidden rounded-lg border border-line bg-paper-card shadow-warm-sm">
+      <ul className="divide-y divide-line-soft">
+        {shown.map((repo) => (
+          <li key={repo.slug}>
+            <Link
+              viewTransition
+              to={`/p/${repo.slug}`}
+              className="flex flex-wrap items-center gap-2.5 px-4 py-3 transition-colors hover:bg-paper-deep/30"
+            >
+              <GitLevelBadge level={repo.level} />
+              <span className="font-display text-sm text-ink">{repo.name}</span>
+              <span className="font-mono text-[0.6875rem] text-ink-faint">{formatGitBranch(repo)}</span>
+              {repo.identityMismatch && (
+                <span className="rounded-md border border-danger/35 bg-danger-bg px-1.5 py-0.5 font-mono text-[0.625rem] font-medium tracking-wide text-danger">
+                  identité incohérente
+                </span>
+              )}
+              <span className="ml-auto font-mono text-[0.6875rem] text-ink-soft">{formatGitSync(repo)}</span>
+            </Link>
+          </li>
+        ))}
+      </ul>
+      {rest > 0 && (
+        <button
+          type="button"
+          onClick={onSeeAll}
+          className="flex w-full cursor-pointer items-center justify-center gap-1 border-t border-line-soft px-4 py-2.5 font-mono text-[0.75rem] font-medium text-copper-deep transition-colors hover:bg-paper-deep/30"
+        >
+          + {rest} autre{rest > 1 ? 's' : ''}
+          <ChevronRight className="h-3.5 w-3.5" aria-hidden />
+        </button>
+      )}
+    </div>
+  );
+}
