+++ b/src/components/git/gitWatchPanelState.ts
@@ -0,0 +1,26 @@
+import type { GitStatusPhase } from '../../hooks/useGitStatus';
+
+/**
+ * Décision PURE de ce que `GitWatchPanel` doit rendre — extraite pour rester
+ * testable unitairement (le composant JSX lui-même n'a pas d'infra de rendu
+ * React dans ce repo, voir `gitSort.ts`/`gitFormat.ts` pour le même idiome).
+ *
+ * FIX P2 (revue adversariale) : `repos.length === 0` (rien n'a encore été
+ * scanné) et `watch.length === 0 && repos.length > 0` (vrai « tout propre »)
+ * sont deux états DISTINCTS — les confondre affirmait faussement une
+ * tranquillité jamais vérifiée (interdit cardinal de l'observatoire). Le
+ * panneau doit donc distinguer explicitement `'unscanned'` de `'clean'`.
+ */
+export type GitWatchPanelState = 'loading' | 'error' | 'unscanned' | 'clean' | 'list';
+
+export function computeGitWatchPanelState(
+  status: GitStatusPhase,
+  reposLength: number,
+  watchLength: number,
+): GitWatchPanelState {
+  if (status === 'loading') return 'loading';
+  if (status === 'error') return 'error';
+  if (reposLength === 0) return 'unscanned';
+  if (watchLength === 0) return 'clean';
+  return 'list';
+}

