--- /dev/null
+++ b/src/components/git/gitFormat.ts
@@ -0,0 +1,71 @@
+import type { GitRepoDetail, GitRepoSummary } from '../../types/git';
+
+/**
+ * Formatteurs texte purs partagés entre `GitStatusTable` (≥ md) et
+ * `GitRepoCard` (< md) — même vocabulaire des deux côtés, jamais de
+ * `dangerouslySetInnerHTML` (spec § 03, verrou « rendu texte pur »).
+ */
+
+export function formatGitBranch(repo: Pick<GitRepoSummary, 'initial' | 'currentBranch' | 'detachedOid'>): string {
+  if (repo.initial) return '(initial)';
+  if (repo.currentBranch) return repo.currentBranch;
+  if (repo.detachedOid) return `détaché (${repo.detachedOid.slice(0, 7)})`;
+  return '(détaché)';
+}
+
+export function formatGitDirty(repo: Pick<GitRepoSummary, 'dirty'>): string {
+  const { staged, unstaged, untracked, submodules } = repo.dirty;
+  const total = staged + unstaged + untracked + submodules;
+  return total === 0 ? '—' : `${total} fichier${total > 1 ? 's' : ''}`;
+}
+
+/**
+ * Colonne « synchro » (spec § 01) : le signal exact et critique est
+ * "jamais poussé" (`aheadTotal`, exact — refs locales) ; à défaut, la
+ * fraîcheur des refs distantes (`refsFreshness`, approximative sans fetch
+ * réseau — Q4 tranchée) — jamais le mot « à jour » : sans fetch, ce n'est
+ * JAMAIS une certitude (même alignement que `syncCell`,
+ * `server/cli/git.ts`, qui retombe sur `-` quand `aheadTotal === 0` plutôt
+ * que d'affirmer quoi que ce soit). Un `ageDays` inconnu ou grand ne doit
+ * jamais se lire comme "c'est bon, c'est à jour".
+ */
+export function formatGitSync(repo: Pick<GitRepoSummary, 'aheadTotal' | 'refsFreshness'>): string {
+  if (repo.aheadTotal > 0) {
+    return `↑ ${repo.aheadTotal} non poussé${repo.aheadTotal > 1 ? 's' : ''}`;
+  }
+  const { ageDays } = repo.refsFreshness;
+  if (ageDays === null) return 'fraîcheur inconnue';
+  if (ageDays === 0) return 'refs de moins d’un jour';
+  return `refs vieilles de ${ageDays} j`;
+}
+
+export function formatGitIdentity(repo: Pick<GitRepoSummary, 'identity'>): string {
+  const id = repo.identity;
+  if (id.accountLabel) return id.accountLabel;
+  if (id.scheme === 'none') return 'sans remote';
+  if (id.scheme === 'multiple') return 'remotes multiples';
+  if (id.scheme === 'https') return 'https (protocole non conforme)';
+  return 'alias inconnu';
+}
+
+/** Libellés d'affichage des 4 providers connus, dans un ordre stable — mirroir
+ *  de `gitContext.ts:PROVIDER_LABELS` / `server/cli/git.ts:PROVIDER_LABELS`. */
+const PROVIDER_LABELS: readonly ['vercel' | 'cloudflare' | 'convex' | 'workos', string][] = [
+  ['vercel', 'Vercel'],
+  ['cloudflare', 'Cloudflare'],
+  ['convex', 'Convex'],
+  ['workos', 'WorkOS'],
+];
+
+/**
+ * LOT 8 — « Vercel=equipe-eosa Convex=proj-frq » à partir du registre
+ * providers in-repo (`detail.providerAccounts`, lu en lecture seule par le
+ * scanner) ; `null` si rien de déclaré (repo qui n'a pas encore committé son
+ * `.claude/.workstation-accounts.json`, ou registre déclaré mais vide).
+ */
+export function formatDeclaredProviderAccounts(detail: Pick<GitRepoDetail, 'providerAccounts'>): string | null {
+  const declared = detail.providerAccounts?.providers;
+  if (!declared) return null;
+  const parts = PROVIDER_LABELS.filter(([key]) => declared[key]).map(([key, label]) => `${label}=${declared[key]}`);
+  return parts.length > 0 ? parts.join(' ') : null;
+}
