+/**
+ * Geste rapide « déclarer les comptes » (LOT 8, spec § 05 / Q6) — construit le
+ * titre et le prompt d'un CHIP prérempli qui demande à un agent LLM d'ÉCRIRE
+ * ET COMMITER `.claude/.workstation-accounts.json` DANS LE REPO CIBLE. Le hub
+ * ne modifie JAMAIS un fichier tracké d'un autre repo (doctrine Galley, Q6) —
+ * il ne fait que proposer le geste. Fonctions PURES, testables sans DOM ni
+ * réseau ; `GitDetailPanel.tsx` ne fait qu'appeler `POST /api/chips` (`cwd` =
+ * chemin absolu du repo cible, JAMAIS celui de la workstation).
+ */
+
+export function buildDeclareAccountsChipTitle(repoName: string): string {
+  return `Déclarer les comptes providers de ${repoName}`;
+}
+
+export function buildDeclareAccountsChipTldr(repoName: string): string {
+  return `Écrire et committer .claude/.workstation-accounts.json (comptes providers + identité git attendue) dans ${repoName}.`;
+}
+
+export function buildDeclareAccountsChipPrompt(repo: { name: string; path: string }): string {
+  return [
+    `Déclare les comptes providers et l'identité git attendue du projet "${repo.name}".`,
+    '',
+    `Crée (ou mets à jour) le fichier suivant, à la racine de CE repo (${repo.path}) :`,
+    '  .claude/.workstation-accounts.json',
+    '',
+    "Format exact (JSON, LIBELLÉS uniquement — JAMAIS de valeur secrète, les valeurs réelles restent au Coffre) :",
+    '{',
+    '  "schemaVersion": 1,',
+    '  "expectedGitAccount": "perso" | "automintech" | "cobacam",',
+    '  "providers": {',
+    '    "vercel": "<libellé du compte Vercel>",',
+    '    "cloudflare": "<libellé du compte Cloudflare>",',
+    '    "convex": "<libellé du compte Convex>",',
+    '    "workos": "<libellé du compte WorkOS>"',
+    '  },',
+    '  "envNotes": "<notes brèves : quelles variables diffèrent entre dev et prod>"',
+    '}',
+    '',
+    'Règles :',
+    '- Tous les champs de "providers" sont optionnels — ne déclare que ce qui est pertinent pour ce projet.',
+    '- "expectedGitAccount" doit être le compte GitHub que CE repo devrait utiliser (perso / automintech / cobacam) — voir GITHUB_ACCOUNTS dans server/config.ts de la workstation.',
+    "- AUCUNE valeur secrète (token, clé API, mot de passe) dans ce fichier — protocole complet : docs/provider-accounts.md du repo workstation.",
+    "- Une fois écrit, committe ce fichier DANS CE REPO (pas dans workstation) : le hub le lit en lecture seule, il ne l'écrit jamais lui-même.",
+  ].join('\n');
+}

