--- /dev/null
+++ b/server/routes/git.test.ts
@@ -0,0 +1,147 @@
+import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
+import { execFileSync } from 'node:child_process';
+import os from 'node:os';
+import path from 'node:path';
+import type { Server } from 'node:http';
+import { mkdir, mkdtemp, realpath, rm } from 'node:fs/promises';
+import express from 'express';
+
+import { GitRepoDetailSchema, GitRepoSummarySchema } from '../../src/types/git';
+
+/**
+ * Route tests pour l'Observatoire Git (LOT 3) — même pattern que
+ * `routes/chips.test.ts` : app Express réelle sur un port éphémère
+ * (`listen(0)`), `fetch` réel, fixtures git RÉELLES (`execFileSync`, pas de
+ * mock) sous un `PROJECTS_ROOT` temporaire (`realpath` — `/tmp` ->
+ * `/private/tmp` sur macOS, requis par le containment défensif de la route).
+ *
+ * `projectsRoot()` (server/config.ts) lit `process.env.PROJECTS_ROOT` À
+ * L'APPEL — contrairement à `ROOT`/`WORKSTATION_ROOT`, ce n'est PAS une const
+ * figée au premier import. Poser la variable avant `beforeAll` suffit, aucune
+ * contrainte d'ordre d'import entre fichiers de test partageant le process.
+ */
+
+let projectsRoot = '';
+let baseUrl = '';
+let server: Server;
+let repoASlug = '';
+
+const prevProjectsRoot = process.env.PROJECTS_ROOT;
+
+function git(args: string[], cwd: string): void {
+  execFileSync('git', args, { cwd, stdio: ['ignore', 'ignore', 'ignore'] });
+}
+
+interface JsonResponse {
+  status: number;
+  json: unknown;
+}
+
+async function req(urlPath: string): Promise<JsonResponse> {
+  const res = await fetch(`${baseUrl}${urlPath}`);
+  let json: unknown = null;
+  try {
+    json = await res.json();
+  } catch {
+    // Pas de corps JSON — acceptable pour certaines réponses d'erreur.
+  }
+  return { status: res.status, json };
+}
+
+beforeAll(async () => {
+  projectsRoot = await realpath(await mkdtemp(path.join(os.tmpdir(), 'ws-gitroutes-')));
+  process.env.PROJECTS_ROOT = projectsRoot;
+
+  const repoADir = path.join(projectsRoot, 'repo-a');
+  await mkdir(repoADir, { recursive: true });
+  git(['init', '-q', '-b', 'main', '.'], repoADir);
+  git(['config', 'user.email', 'fixture@example.invalid'], repoADir);
+  git(['config', 'user.name', 'Fixture'], repoADir);
+  git(['commit', '-q', '--allow-empty', '-m', 'init'], repoADir);
+
+  const { slugify } = await import('../services/slug');
+  repoASlug = slugify('repo-a');
+
+  const { gitRouter } = await import('./git');
+
+  const app = express();
+  app.use('/api/git', gitRouter);
+
+  await new Promise<void>((resolve) => {
+    server = app.listen(0, '127.0.0.1', () => resolve());
+  });
+  const address = server.address();
+  const port = typeof address === 'object' && address ? address.port : 0;
+  baseUrl = `http://127.0.0.1:${port}/api/git`;
+});
+
+afterAll(async () => {
+  await new Promise<void>((resolve, reject) => {
+    server.close((err) => (err ? reject(err) : resolve()));
+  });
+  if (projectsRoot) await rm(projectsRoot, { recursive: true, force: true });
+  if (prevProjectsRoot === undefined) delete process.env.PROJECTS_ROOT;
+  else process.env.PROJECTS_ROOT = prevProjectsRoot;
+});
+
+describe('GET /api/git/status', () => {
+  test('200, chaque repo valide GitRepoSummarySchema', async () => {
+    const res = await req('/status');
+    expect(res.status).toBe(200);
+    const { repos } = res.json as { repos: unknown[] };
+    expect(repos.length).toBeGreaterThan(0);
+    for (const r of repos) {
+      const parsed = GitRepoSummarySchema.safeParse(r);
+      expect(parsed.success).toBe(true);
+    }
+  });
+
+  test('inclut le dépôt fixture repo-a', async () => {
+    const res = await req('/status');
+    const { repos } = res.json as { repos: { slug: string }[] };
+    expect(repos.some((r) => r.slug === repoASlug)).toBe(true);
+  });
+
+  test('refresh=1 deux fois de suite -> la seconde est throttled', async () => {
+    const first = await req('/status?refresh=1');
+    expect(first.status).toBe(200);
+    const second = await req('/status?refresh=1');
+    expect(second.status).toBe(200);
+    expect((second.json as { throttled?: boolean }).throttled).toBe(true);
+  });
+
+  test('sans refresh, pas de champ throttled', async () => {
+    const res = await req('/status');
+    expect(res.status).toBe(200);
+    expect((res.json as { throttled?: boolean }).throttled).toBeUndefined();
+  });
+});
+
+describe('GET /api/git/:slug', () => {
+  test('slug connu -> 200, GitRepoDetailSchema valide', async () => {
+    const res = await req(`/${repoASlug}`);
+    expect(res.status).toBe(200);
+    const parsed = GitRepoDetailSchema.safeParse(res.json);
+    expect(parsed.success).toBe(true);
+    expect((res.json as { slug: string }).slug).toBe(repoASlug);
+  });
+
+  test('slug bien formé mais inconnu -> 404', async () => {
+    const res = await req('/repo-does-not-exist-anywhere');
+    expect(res.status).toBe(404);
+  });
+
+  test('slug avec ".." littéral -> 400', async () => {
+    const res = await req('/demo..evil');
+    expect(res.status).toBe(400);
+  });
+
+  test('slug avec traversal encodé (..%2f..%2fetc) -> 400 (ou 404, jamais 200/500)', async () => {
+    // Selon la normalisation d'Express, `%2f` peut soit atteindre le handler
+    // (isSafeSegment -> 400) soit être rejeté en amont par le routeur
+    // (404 "aucune route ne matche") — jamais un accès disque (200) et jamais
+    // un crash serveur (500) : c'est la garantie de sécurité vérifiée ici.
+    const res = await req('/..%2f..%2fetc');
+    expect([400, 404]).toContain(res.status);
+  });
+});

